export default [{"id":25,"question":"ما الحكمة في أنَّ النبي ﷺ يُصلي على الجنازة عند صدر الرجل ووسط المرأة؟","title":"ما موضع الوقوف بالجنازة؟ وما حكمته؟","answer":"الجواب: السُّنة أنه يقف عند رأس الرجل، ما هو عند صدره، عند الصدر هذا من كلام بعض الفقهاء، لا دليلَ عليه، وإنما الثابت من حديث أنسٍ وغيره الوقوف عند رأس الرجل، وعند وسط المرأة، يُحاذي وسطها، ويُحاذي رأس الرجل عند الصلاة عليهما، هذا هو المحفوظ عن النبي ﷺ.\nأما الحكمة: فالله أعلم، هذا تعبّد تعبّدنا الله به، وعلينا أن نتأسَّى بالرسول ﷺ، أما الحكمة فللناس كلامٌ لا دليلَ عليه في ذلك، والله يقول جلَّ وعلا: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، ويقول النبيُّ ﷺ: صلُّوا كما رأيتموني أُصلي، فعلينا أن نُصلي كما صلَّى، فإن علمنا الحكمة فهذا خيرٌ إلى خيرٍ، ونورٌ على نورٍ، وإن لم نعلم فلا حرج علينا، ولا أعلم شيئًا واضحًا في الحكمة من جهة رأس الرجل، ومن جهة وسط المرأة.","link":"https://binbaz.org.sa/fatwas/2805/ما-موضع-الوقوف-بالجنازة-وما-حكمته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0278.mp3","categories":["الصلاة على الميت"]},{"id":361,"question":"هل تجب الصلاة على الجنين والصَّدقة عنه إذا مرَّ على حمله شهران أو أقلّ؟","title":"ما حكم الصلاة على الجنين السَّقط؟","answer":"الجواب: الجنين يختلف: فإذا كان الجنين قد جاوز الأربعة، ونُفخت فيه الروح، فهذا إذا سقط يُغَسَّل ويُصلَّى عليه، ويُسمَّى ويُعقّ عنه، أفضل، هذا ما نصَّ عليه أهلُ العلم.\nأما إذا كان قبل ذلك فهذا لا يُغسَّل، ولا يُصلَّى عليه، وليس بجنينٍ حتى يتخلَّق وتُنفخ فيه الروح، إذا سقط لحمةً أو دمًا فهذا ليس بشيءٍ، فلا يُغسَّل، ولا يُصلَّى عليه، وإنما يُغسَّل ويُصلَّى عليه ويُسمَّى إذا سقط بعد الأربعة أشهر، ونُفخت الروح فيه.","link":"https://binbaz.org.sa/fatwas/4556/ما-حكم-الصلاة-على-الجنين-السقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0415.mp3","categories":["الصلاة على الميت"]},{"id":1389,"question":"أراد أن يصلي على جنازة في مسجد فتذكر أن له شيئًا آخر في مسجد آخر فاستقبل الجنازة قبل الصلاة وصلى عليها ثم خرج إلى المسجد الثاني وحده، يقول: ما حكم صلاتي؟ وهل يشترط لصلاة الجنازة وضوء أم لا؟","title":"هل يشترط الوضوء والجماعة لصلاة الجنازة؟","answer":"الجواب:\nلا بدّ من الوضوء لصلاة الجنازة مثل غيرها من الصلوات.\nس: وصلاته التي صلاها؟\nج: لو صلى وحده ما يضر، ما يشترط لها الجماعة.","link":"https://binbaz.org.sa/fatwas/21482/هل-يشترط-الوضوء-والجماعة-لصلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في صلاة الجنازة وهل يشترط الجماعة لها.mp3","categories":["الصلاة على الميت"]},{"id":1513,"question":"هل يُؤخذ من حديث المرأة السوداء أنه تجوز الصلاة في المقبرة؟","title":"حكم الصلاة على الميت في المقبرة","answer":"الجواب:\nالصلاة على الميت في القبور نعم، لا بأس، أما الذي لا يجوز فهي الصلاة ذات الركوع والسجود، أما الصلاة على الميت في المقبرة فلا بأس، فعلها النبيُّ ﷺ.......\nتُسمَّى صلاة الجنازة، وهي دعاء، فمقصودها الدعاء، فإذا صلَّى على القبر فلا بأس، فعله النبيُّ ﷺ.\nس: وإن مضى وقتٌ طويلٌ؟\nج: لشهرٍ فأقل، إذا كان ما مضى عليه إلا شهرٌ أو حوله يُصلَّى على قبره.","link":"https://binbaz.org.sa/fatwas/21612/حكم-الصلاة-على-الميت-في-المقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة على الميت في المقبرة.mp3","categories":["الصلاة على الميت"]},{"id":2106,"question":"رجلٌ يأتي عند مسجدٍ تكثر فيه الجنائز، فيأتي بعد الجنائز بأحد عشر مترًا، فيُصلي عليها وحده، ثم يذهب إلى مسجدٍ آخر يُصلِّي فيه، ويقول: ما حكم صلاتي؟","title":"هل طلب العلم أفضل أم تحرِّي صلاة الجنازة؟","answer":"الجواب:\nيُصلي على الجنازة وحده؟\nس: نعم، وحده.\nج: وأيش الدليل؟\nس: يقول: حتى أجمع بين طلب العلم والصلاة على الجنازة.\nج: لا، إمَّا أن يُصلي عليها مع المسلمين، أو يُصلي في المسجد الذي يطلب فيه العلم، وطلب العلم أهم.\nس: لكن هل صلاته على الجنازة وحده باطلة؟\nج: لا، ليست باطلةً، إذا صلَّى عليها لا بأس، لكن كونه يُصلي مع المسلمين الفريضة ثم يُصلي على الجنائز أفضل، وإذا كان قصده طلب العلم فعليه أن يلتمس المسجد الذي فيه طلب العلم، وهذا أفضل له من طلب الجنائز.\nس: يريد أن يجمع بين الأمرين؟\nج: لا، لا يجمع بين الأمرين، يذهب إلى طلب العلم، والحمد لله.","link":"https://binbaz.org.sa/fatwas/22224/هل-طلب-العلم-افضل-ام-تحري-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين طلب العلم والصلاة على الجنازة.mp3","categories":["الصلاة على الميت"]},{"id":2149,"question":"الرجل الذي عليه دين وتُوُفِّي، هل يُصلَّى عليه؟","title":"هل يُصلَّى على مَن تُوُفِّي وعليه دَيْن؟","answer":"الجواب:\nيُصَلَّى عليه ويُوفَى عنه.\nس: كان قادرًا لكنه ما استطاع...؟\nج: ولو، يُصلَّى عليه، فالنبي ترك الصلاة أولًا، ثم أمر بالصلاة فقال: صلّوا على صاحبكم.","link":"https://binbaz.org.sa/fatwas/22268/هل-يصلى-على-من-توفي-وعليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُصلَّى على من توفي وعليه دين.mp3","categories":["الصلاة على الميت"]},{"id":2577,"question":"ورد في رواية عند البخاري ومسلم صلاته ﷺ على الميت؟","title":"معنى صلاة النبي ﷺ على قتلى أُحد","answer":"الجواب: لا، هذا كلامهم، صلاته يعني: دعاؤه للميت، هذا المعروف عند أهل العلم، معناه: دعاؤه للميت؛ لأنه ثبت في الأحاديث الصحيحة أن القتلى الشهداء في سبيل الله لا يُصلى عليهم.","link":"https://binbaz.org.sa/fatwas/22710/معنى-صلاة-النبي-ﷺ-على-قتلى-احد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة النبي عليه الصلاة والسلام على قتلى أحد صلاته على الميت.mp3","categories":["الصلاة على الميت"]},{"id":2584,"question":"هل يُصلّى على الغريق؟","title":"هل يُصلّى على الغريق؟","answer":"الجواب: الغريق يُصلّى عليه، كل الشهداء يُصلّى عليهم إلا شهيد المعركة في القتل، وإلا الشهداء كلهم يُصلّى عليهم، إلا شهيد المعركة.","link":"https://binbaz.org.sa/fatwas/22717/هل-يصلى-على-الغريق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة على الغريق.mp3","categories":["الصلاة على الميت"]},{"id":2735,"question":"الغريق والمهدوم يصلى عليهم؟","title":"هل يُصَلى على الغريق والمهدوم؟","answer":"الجواب: نعم، كل الشهداء يُصلى عليهم إلا شهيد المعركة خاصة، من مات في المعركة، مثل ما غُسّل عمر وغيره وعثمان وصُلِّي عليهم.\nس: يُغَسّلون؟\nالشيخ: يُغَسّلون ويُصلّى عليهم ويكفّنون، إلا شهيد المعركة الذي يموت في المعركة، يُقتل في المعركة.","link":"https://binbaz.org.sa/fatwas/22883/هل-يصلى-على-الغريق-والمهدوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُصَلى على الغريق والمهدوم.mp3","categories":["الصلاة على الميت"]},{"id":2747,"question":"رفع اليد في تكبيرات الجنازة؟","title":"حكم رفع اليد في تكبيرات الجنازة","answer":"الجواب: أفْضَلُ الرَّفْعُ، كالأُولى، كما جاء عن ابن عباس وغيره.\nس: هل في حديث ثبت عن الرسول ﷺ؟\nالشيخ: في حديث عن ابن عمر رواه الدارقطني بسند جيد.","link":"https://binbaz.org.sa/fatwas/22895/حكم-رفع-اليد-في-تكبيرات-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم رفع اليد في تكبيرات الجنازة.mp3","categories":["الصلاة على الميت"]},{"id":3020,"question":"عندما نبش أحدُ الصحابة قبر أبيه هل يُؤخذ منه جوازُ ذلك؟","title":"هل يجوز نُبْشُ القبر؟","answer":"الجواب: هذا جابر بن عبدالله، إذا رأى المصلحة مثل: المحل ما هو مناسب، أو محل سيل، أو محل طُرُق، أو يكون معه آخر؛ وحب أن يفرق كل واحد لحاله، ما في بأس؛ للمصلحة؛ لأن الرسول ﷺ ما أنكر على جابر.","link":"https://binbaz.org.sa/fatwas/23179/هل-يجوز-نبش-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز نبش القبر.mp3","categories":["حرمة الأموات","الصلاة على الميت"]},{"id":3229,"question":"أولاد المشركين يُصلى عليهم إذا ماتوا؟","title":"هل يُصَلى على مَنْ مات مِنْ أولاد المشركين؟","answer":"الجواب: لا، في الدنيا لهم أحكامُ أهلِهم، لا يُصلى عليهم، النبي ﷺ قال: هم منهم لا يُصلى عليهم في الدنيا، لهم أحكامهم في الدنيا لو قُتلوا، يعني لو فوجئ أهلهم وبُيِّتُوا ومات منهم أولاد؛ تَبَعُ أهلهم قال ﷺ: هم منهم في أحكام الدنيا معهم، لكن في أحكام الآخرة لهم النجاة إذا لم يبلغوا.","link":"https://binbaz.org.sa/fatwas/23392/هل-يصلى-على-من-مات-من-اولاد-المشركين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُصَلى على أولاد المشركين.mp3","categories":["الصلاة على الميت"]},{"id":3386,"question":"يحصل في بعض المصليات في الجنائز إذا كان هناك مجموعة جنائز نساء ورجال، أن يُقدّم الرجال، ويُنكر بشدة لو قُدّمت المرأة، هل لهذا الإنكار وجه؟","title":"حكم تقديم جنائز الرجال على جنائز النساء","answer":"الجواب: السُّنة تقديم الرجال، هذا السُّنة يُقدّم الرجال إلى الإمام ثم النساء بعد ذلك، ويكون وسط المرأة عند رأس الرجل حتى يُصلِّي عليهم جميعًا، فإذا كان رجل وامرأة: يُقدّم الرجل إلى الإمام ثم المرأة خلفه وسطها إلى عند رأس الرجل، وإن كان فيه أطفال فالطفل الذكر بعد الذكر، ثم الأنثى، ثم الطفلة الأنثى.","link":"https://binbaz.org.sa/fatwas/23554/حكم-تقديم-جناىز-الرجال-على-جناىز-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من السنة تقديم جنائز الرجال على جنائز النساء.mp3","categories":["الصلاة على الميت"]},{"id":3387,"question":"يُصلى على المرأة الحائض في المسجد؟","title":"هل يُصَلّى على الحائض بالمسجد إذا ماتت؟","answer":"الجواب: نعم، لا بأس، النبي ﷺ صلى على النساء في المسجد ولم يسأل.","link":"https://binbaz.org.sa/fatwas/23555/هل-يصلى-على-الحاىض-بالمسجد-اذا-ماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُصَلّى على المرأة الحائض في المسجد إذا ماتت.mp3","categories":["المساجد ومواضع السجود","زكاة النقدين","الصلاة على الميت","أحكام التعزية"]},{"id":3388,"question":"المشروع أن يقول: صلوا على الميتة، أو الميت، أو الجنازة؟","title":"ما حكم تعيين صاحب الجنازة لتنبيه الناس؟","answer":"الجواب: من باب التنبيه، إذا دعت الحاجة؛ حتى يعلم الناس أنها جنازة، من باب التنبيه، فإذا كانت الصفوف كثيرة يُخشى ألا يفهموا، ولا يعلموا، أما إذا كان قليلين ما يحتاج تنبيه.\nس: إذا كان تعيين: رجل، امرأة، رجال؟\nالشيخ: إن عيّن فلا بأس، حتى يقول: اللهم اغفر لها، وارحمها، اللهم اغفر له، وارحمه، وإن لم يبيّن فلا حرج، إذا قال: اللهم اغفر له؛ يكفي، يَعُمّ الجميع.","link":"https://binbaz.org.sa/fatwas/23556/ما-حكم-تعيين-صاحب-الجنازة-لتنبيه-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل متفرقة في الصلاة على الجنازة.mp3","categories":["الصلاة على الميت"]},{"id":3446,"question":"تُنبش لحاجة؟","title":"هل يجوز نَبْشُ القبور للحاجة؟","answer":"الجواب: نعم، إذا دعت الحاجة إلى هذا تُنبش، وتُبعد، ويُتخذ مكانها مسجدًا، أو بيوتًا، أو غير ذلك.\nس: وكذا يدخل فيها قبورُ المشركين؟\nالشيخ: نعم، الكلام في قبور المشركين، أما قبور المسلمين لا تُنبش، تبقى في محلها.","link":"https://binbaz.org.sa/fatwas/23621/هل-يجوز-نبش-القبور-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تنبش القبور للحاجة.mp3","categories":["حرمة الأموات","الصلاة على الميت"]},{"id":3448,"question":"إذا قدمت جنازة للإمام، وعلم أحد المأمومين بأنه لا يصلي إطلاقًا؛ هل يسوغ شرعًا أن يُخبر الإمام؟","title":"حكم مَنْ عَلِمَ أن صاحب الجنازة لم يكن يُصلي","answer":"الجواب: الظاهر أنه لا يصلي إذا كان يعلم ذلك، وإلا شهادته قد لا تُقبل وحده، لكن هو إذا ترك الصلاة عليه فهو الذي ينبغي، إذا كان يعلم أنه لا يصلي.","link":"https://binbaz.org.sa/fatwas/23623/حكم-من-علم-ان-صاحب-الجنازة-لم-يكن-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا قدمت جنازة ليُصَلى عليها وعلم أحد المأمومين بأنه لا يصلي إطلاقًا، فهل يخبر الإمام.mp3","categories":["الصلاة على الميت"]},{"id":3460,"question":"إذا دخل رجل المسجد بعدما صلوا الجماعة، ثم قامت جماعة أخرى، وقدمت جنازة ليُصلى عليها فهل يصلي على الجنازة؟","title":"هل يَبدأ بالجنازة الحاضرة مَنْ فاتته فريضة؟","answer":"الجواب: يبدأ بالجنازة، ثم يصلي مع الناس؛ لأن الجنازة تفوت، والقضاء لا يفوت.","link":"https://binbaz.org.sa/fatwas/23637/هل-يبدا-بالجنازة-الحاضرة-من-فاتته-فريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دخل المسجد بعد الجماعة، وقدمت جنازة ليصلى عليها فهل يصلي الفريضة أم الجنازة.mp3","categories":["الصلاة على الميت"]},{"id":3477,"question":"يسأل بعض الإخوة الحاضرين يقول يذهب بعض الإخوان للصلاة في المساجد التي يُصلى بها على الجنائز، فأنكر عليه بعضهم بحجة أن السلف لم يكونوا يتتبعون الجنائز، ما رأيكم في هذا؟","title":"حكم تتبع المساجد التي فيها جنائز","answer":"الجواب: الإنكار لا وجه له، ما دام أن الرسول حث على الصلاة على الجنازة فإذا عُرف أن المسجد فيه جنازة، وذهب يصلي عليها فهو مأجور قاصدًا صلاة الجنازة التي رغب فيها النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/23654/حكم-تتبع-المساجد-التي-فيها-جناىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تتبع المساجد التي فيها جنائز.mp3","categories":["الصلاة على الميت"]},{"id":3503,"question":"إمام لا يصلي على الجنازة بعد العصر فيقدمون الجنائز قبل صلاة الفرض؟","title":"ما حكم الصلاة على الجنازة بعد العصر؟","answer":"الجواب: لا بأس بهذا؛ لأنها من ذوات الأسباب.\nس: لكن يُنكر عليه؟\nالشيخ: لا، بعد الصلاة يُعَلّم السُّنة.","link":"https://binbaz.org.sa/fatwas/23683/ما-حكم-الصلاة-على-الجنازة-بعد-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة على الجنازة بعد العصر.mp3","categories":["الصلاة على الميت"]},{"id":4545,"question":"الصلاة على الميت في المقبرة أو أفضل في المسجد؟","title":"هل صلاة الجنازة في المقبرة أفضل أم المسجد؟","answer":"الجواب: في المصلى، وفي المساجد، وإذا دعت الحاجةُ إلى الصلاة في المقبرة فلا بأس؛ صلَّى النبيُّ ﷺ في المقبرة على جنازةٍ، لكن في المصليات أفضل وفي المساجد حتى يجتمع الناس.\nس: في المسجد؟\nج: في المسجد، وفي المصلَّى، كله طيب.","link":"https://binbaz.org.sa/fatwas/24825/هل-صلاة-الجنازة-في-المقبرة-افضل-ام-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما أفضل في الصلاة على الميت في المقبرة أو في المسجد.mp3","categories":["الصلاة على الميت"]},{"id":4955,"question":"إذا شك في الجنازة هل هي سنية، أو رافضية، أو غير ذلك، فهل يشترط؟","title":"هل يجوز الاشتراط لمَنْ شَكّ في اعتقاد الميت؟","answer":"الجواب: ما دام بين المسلمين يصلي عليها، والحمد لله، إلا أن يعلم أنها ممنوع الصلاة عليها، إلا أن يعلم أنها كافرة.\nس: أحسن الله إليك، نقل ابن القيم عن شيخ الإسلام؟\nالشيخ: الاشتراط ما عليه دليل.","link":"https://binbaz.org.sa/fatwas/27526/هل-يجوز-الاشتراط-لمن-شك-في-اعتقاد-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز الاشتراط لمن شكّ في اعتقاد الميت؟.mp3","categories":["الصلاة على الميت"]},{"id":4956,"question":"إذا تعدّدت الجنائز هل يكون لكل جنازة قيراط أجر؟","title":"هل يزيد أجر صلاة الجنازة بتعدد الجنائز؟","answer":"الجواب: يُرجى له، إذا صلى خمسًا له أجر صلاة على خمس جنائز، الحمد لله.","link":"https://binbaz.org.sa/fatwas/27560/هل-يزيد-اجر-صلاة-الجنازة بتعدد-الجناىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يزيد أجر صلاة الجنازة بتعدد الجنائز؟.mp3","categories":["الصلاة على الميت"]},{"id":4957,"question":"يقول بعض الفقهاء أن المصلي على الميت له أن يقف على صدر الرجل؟","title":"أين يقف المُصلي على جنازة الرجل والمرأة؟","answer":"الجواب: لا، السنة عند الرأس، هذا هو الثابت في الأحاديث الصحيحة، وعند عَجُز المرأة، عند وسط المرأة، كما في حديث أنس .","link":"https://binbaz.org.sa/fatwas/27559/اين-يقف-المصلي-على-جنازة-الرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أين يقف المُصلي على جنازة الرجل والمرأة؟.mp3","categories":["الصلاة على الميت"]},{"id":5443,"question":"الطفل كيف يكبر عليه؟","title":"كيف يكون الدعاء في جنازة الصغير؟","answer":"الجواب: الطفل يُكبِّر عليه أربعًا مثل الكبير، ويقول في الدعاء الأخير بعد الثالثة بعدما يقول: اللهم اغفر لحينا وميتنا، وشاهدنا وغائبنا، وصغيرنا وكبيرنا، وذكرنا وأُنثانا، اللهم مَن أحييتَه منا فأحيه على الإسلام، ومَن توفيتَه منا فتوفه على الإيمان، يقول بعده: \"اللهم اجعله ذخرًا لوالديه\" هذا دعاء عام، \"اللهم اجعله ذخرًا لوالديه، وفرطًا، وشفيعًا مجابًا، اللهم عظِّم أجورهما، وثقِّل به موازينهما، وألحقه بالصالحين، واجعله في كفالة إبراهيم ، وقِهِ وأهله عذابَ الجحيم\"، هذا ما ورد في حقِّ الطفل.[1]","link":"https://binbaz.org.sa/fatwas/31241/كيف-يكون-الدعاء-في-جنازة-الصغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 059.mp3","categories":["الصلاة على الميت"]},{"id":5704,"question":"هل يصلى على قاتل نفسه، والتارك للجمعة والجماعة، وآكل الربا؟ وهل يصلى على المقتول حدًا؟","title":"حكم الصلاة على مرتكب الكبائر","answer":"الجواب: القاعدة أن العاصي يصلى عليه، العاصي الذي ليس بكافر يصلى عليه، لكن إذا ترك الصلاة عليه بعض الكبار، مثل العالم والقاضي، والرئيس من باب الزجر لغيره، والتنفير من هذا العمل السيئ،؛ لأنه يرابي، أو لأنه قتل نفسه، فهذا من باب التنفير من هذه المعاصي، وإلا فيصلى عليه.  المقصود: أنه لا بدّ من عناية بهذا، فالذي لا يعرف المساجد يظن به السوء -نسأل الله السلامة- لكن لا يقطع بكفره، لا مانع من الصلاة عليه ما دام مع المسلمين، ويشهد أن لا إله إلا الله، وأن محمدًا رسول الله، ويعامل كمعاملة المسلمين، فالأفضل بقاؤه في الإسلام حتى تعلم أنه لا يصلي بالكلية.","link":"https://binbaz.org.sa/fatwas/1013/حكم-الصلاة-على-مرتكب-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_38.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5705,"question":"ثبت أن الرسول ﷺ صلى على جنازة في القبر بعد قبرها بمدة، فهل يجوز للإنسان أن يصلي على قريبه إذا جاء إلى قبره خلال عشرة أيام من موته، أو أقل، أو أكثر؟","title":"هل يصلى على الميت في القبر؟ وما مدة ذلك؟","answer":"الجواب:  السنة الصلاة على القبر، إذا كان ما صلى على الميت يستحب له أن يصلي على القبر، فقد ثبت عنه -عليه الصلاة والسلام- أنه ذكر له أن امرأة كانت تقم المسجد، كانت تكنس المسجد، كانت امرأة سوداء تكنس المسجد، فماتت ليلًا، فغسلها المسلمون، وصلوا عليها، ودفنوها في الليل، ولم يخبروا النبي ﷺ بذلك، وكرهوا أن يوقظوه، فلما أصبح، وأخبروه قال: أفلا كنتم آذنتموني؟! دلوني على قبرها فدلوه على قبرها، فصلى عليها -عليه الصلاة والسلام- وقال: لا يموتن أحد من المسلمين إلا أخبرتموني، فإن الله جاعل من صلاتي عليهم خيرًا لهم، وقال: نورًا لهم عليه الصلاة والسلام. هذه السنة؛ إذا كانت فاتته الصلاة على الميت يستحب للإنسان إذا تيسر له أن يذهب، ويصلي على القبر فهذا سنة، فعله النبي ﷺ مرات -عليه الصلاة والسلام- وفعله على أم سعد، وقد مضى لها شهر.  فذكر العلماء أنه إذا كان شهر، وما حوله، وأقل فلا بأس، وإذا طالت المدة فلا حاجة إلى ذلك؛ لأن الرسول لم يفعل ذلك بعد طول المدة -عليه الصلاة والسلام- إنما فعله في حدود شهر فأقل، أما إذا طالت المدة على الميت فلا يشرع الصلاة عليه لمن غاب عنه.  السؤال: بالنسبة للمسجد الذي كانت تقمه المرأة هل هو مسجد الرسول أو غيره؟ الجواب:  مسجد الرسول ﷺ. السؤال: هل هو رجل، أو امرأة؟ الجواب:  جاء في رواية أنه خادم، وجاء في رواية أنها خادمة، امرأة سوداء، ولا مانع أن يكون خادم وخادمة، وهذا يدل على فضل قم المساجد، وتنظيف المساجد، وأن قمها وتنظيفها من السنة.  وقد أمر النبي ﷺ بأن تبنى المساجد في الدور في القبائل، وأن تنظف، وأن تطيب، وقال -عليه الصلاة والسلام-: عرضت عليّ أجور أمتي حتى القذاة يخرجها الرجل من المسجد يعني عرضت عليه الأجور حتى القذاة، مثل قطعة عود، أو خرقة صغيرة يأخذها الرجل، ويزيلها من المسجد، هذا من الأجور والله أكبر.","link":"https://binbaz.org.sa/fatwas/1011/هل-يصلى-على-الميت-في-القبر-وما-مدة-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_36.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5708,"question":"هل يصلى على قاتل نفسه، والتارك للجمعة والجماعة، وآكل الربا؟ وهل يصلى على المقتول حدًا؟","title":"حكم الصلاة على مرتكب الكبائر","answer":"الجواب: القاعدة أن العاصي يصلى عليه، العاصي الذي ليس بكافر يصلى عليه، لكن إذا ترك الصلاة عليه بعض الكبار، مثل العالم والقاضي، والرئيس من باب الزجر لغيره، والتنفير من هذا العمل السيئ،؛ لأنه يرابي، أو لأنه قتل نفسه، فهذا من باب التنفير من هذه المعاصي، وإلا فيصلى عليه.  المقصود: أنه لا بدّ من عناية بهذا، فالذي لا يعرف المساجد يظن به السوء -نسأل الله السلامة- لكن لا يقطع بكفره، لا مانع من الصلاة عليه ما دام مع المسلمين، ويشهد أن لا إله إلا الله، وأن محمدًا رسول الله، ويعامل كمعاملة المسلمين، فالأفضل بقاؤه في الإسلام حتى تعلم أنه لا يصلي بالكلية.","link":"https://binbaz.org.sa/fatwas/1013/حكم-الصلاة-على-مرتكب-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_38.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5711,"question":"ثبت أن الرسول ﷺ صلى على جنازة في القبر بعد قبرها بمدة، فهل يجوز للإنسان أن يصلي على قريبه إذا جاء إلى قبره خلال عشرة أيام من موته، أو أقل، أو أكثر؟","title":"هل يصلى على الميت في القبر؟ وما مدة ذلك؟","answer":"الجواب:  السنة الصلاة على القبر، إذا كان ما صلى على الميت يستحب له أن يصلي على القبر، فقد ثبت عنه -عليه الصلاة والسلام- أنه ذكر له أن امرأة كانت تقم المسجد، كانت تكنس المسجد، كانت امرأة سوداء تكنس المسجد، فماتت ليلًا، فغسلها المسلمون، وصلوا عليها، ودفنوها في الليل، ولم يخبروا النبي ﷺ بذلك، وكرهوا أن يوقظوه، فلما أصبح، وأخبروه قال: أفلا كنتم آذنتموني؟! دلوني على قبرها فدلوه على قبرها، فصلى عليها -عليه الصلاة والسلام- وقال: لا يموتن أحد من المسلمين إلا أخبرتموني، فإن الله جاعل من صلاتي عليهم خيرًا لهم، وقال: نورًا لهم عليه الصلاة والسلام. هذه السنة؛ إذا كانت فاتته الصلاة على الميت يستحب للإنسان إذا تيسر له أن يذهب، ويصلي على القبر فهذا سنة، فعله النبي ﷺ مرات -عليه الصلاة والسلام- وفعله على أم سعد، وقد مضى لها شهر.  فذكر العلماء أنه إذا كان شهر، وما حوله، وأقل فلا بأس، وإذا طالت المدة فلا حاجة إلى ذلك؛ لأن الرسول لم يفعل ذلك بعد طول المدة -عليه الصلاة والسلام- إنما فعله في حدود شهر فأقل، أما إذا طالت المدة على الميت فلا يشرع الصلاة عليه لمن غاب عنه.  السؤال: بالنسبة للمسجد الذي كانت تقمه المرأة هل هو مسجد الرسول أو غيره؟ الجواب:  مسجد الرسول ﷺ. السؤال: هل هو رجل، أو امرأة؟ الجواب:  جاء في رواية أنه خادم، وجاء في رواية أنها خادمة، امرأة سوداء، ولا مانع أن يكون خادم وخادمة، وهذا يدل على فضل قم المساجد، وتنظيف المساجد، وأن قمها وتنظيفها من السنة.  وقد أمر النبي ﷺ بأن تبنى المساجد في الدور في القبائل، وأن تنظف، وأن تطيب، وقال -عليه الصلاة والسلام-: عرضت عليّ أجور أمتي حتى القذاة يخرجها الرجل من المسجد يعني عرضت عليه الأجور حتى القذاة، مثل قطعة عود، أو خرقة صغيرة يأخذها الرجل، ويزيلها من المسجد، هذا من الأجور والله أكبر.","link":"https://binbaz.org.sa/fatwas/1011/هل-يصلى-على-الميت-في-القبر-وما-مدة-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_36.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5718,"question":"قوله: ويقدم أسن فأسبق يعني عند الصلاة على الجنائز، فهل يجعل الأفضل من قبل القبلة، والمفضول من قبل الإمام يعني بالعكس؟","title":"كيفية وضع الجنائز عند الصلاة عليها","answer":"الجواب: المشهور أنه يقدم الرجال، ثم النساء عند الإمام في الصلاة على الجنائز، يقدم الرجال، ثم الصبيان، ثم النساء في الجنائز، هكذا جاءت النصوص، يقدم أولًا الرجال، ثم النساء يكن من جهة القبلة، ويكون الأفضل إلى الإمام الرجال، ثم الصبيان إلى الإمام، وخلفهم من جهة القبلة النساء، هذا هو المشروع، وهكذا في الصفوف، الصفوف الأول تكون للرجال، ثم الصبيان، ثم النساء خلفهم.  السؤال: ياشيخ، الله يبارك فيك، ما فهنما الكلام هذا، إذا كان فيه رجال ونساء كيف نضعهم؟ الجواب: الجنازة أولًا، الرجل يكون قرب الإمام قريبًا منه، ثم يليه في الصف الصبي، ثم المرأة من جهة القبلة.","link":"https://binbaz.org.sa/fatwas/1030/كيفية-وضع-الجناىز-عند-الصلاة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_52.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5815,"question":"هل قاتل نفسه يغسل، ويصلى عليه؟","title":"حكم الغسل والصلاة على قاتل نفسه","answer":"الجواب: قاتل نفسه يغسل، ويصلى عليه، ويدفن مع المسلمين؛ لأنه عاص ما هو كافر، قتل النفس معصية، ما كفر، فإذا قتل نفسه -والعياذ بالله- يغسل، ويصلى عليه، ويكفن، ويصلى عليه، ويدفن مع المسلمين، لكن ينبغي للإمام الأكبر، ولمن له أهمية أن يترك الصلاة عليه من باب الإنكار، لئلا يظن أنه راض عن عمله.  فالإمام الأكبر السلطان، أو القضاة، أو رئيس البلد، وقاضي البلد، أو أميرها إذا ترك ذلك من باب إنكار هذا الشيء، وإعلان أن هذا خطأ؛ فهذا حسن، ولكن يصلي عليه بعض المسلمين.","link":"https://binbaz.org.sa/fatwas/1145/حكم-الغسل-والصلاة-على-قاتل-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_149.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5819,"question":"هل يجوز تكرار الصلاة على الميت؟","title":"حكم تكرار الصلاة على الميت","answer":"الجواب:  إذا وافق لا بأس، إذا صلى عليه، ثم وافق ناس يصلون عليه، فصلى معهم عند القبر؛ لا بأس، ولا حرج في ذلك، مثل ما يكرر الصلاة الأخرى، فلو صلى في مسجد، ثم جاء إلى مسجد لحاجة، أو لحضور الدرس، وهم يصلون؛ صلى معهم، كما أمر النبي بذلك -عليه الصلاة والسلام- فالإعادة لأمر شرعي لا بأس.","link":"https://binbaz.org.sa/fatwas/1146/حكم-تكرار-الصلاة-على-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_150.mp3","categories":["الصلاة على الميت"]},{"id":5869,"question":"إذا صلى الإمام على الجنائز فهل يجعل الأفضل من قبل القبلة، أم يجعله من قبله، أي مما يليه، وكذلك في القبر؟","title":"كيفية ترتيب الجنائز عند الصلاة","answer":"الجواب: الأفضل مما يليه. السؤال مرة أخرى: يجعل الرجل يليه، والصبي يلي الرجل، ثم المرأة وراء ذلك من جهة القبلة، الجنائز الصف الأول للرجال، والذي يليه للصبيان، ثم النساء متأخرات مثل الصفوف، يلي الإمام الرجال، ثم يلي الرجال الصبيان في الجنائز، ثم النساء من جهة القبلة، هذا هو السنة.","link":"https://binbaz.org.sa/fatwas/1226/كيفية-ترتيب-الجناىز-عند-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_223.mp3","categories":["الصلاة على الميت"]},{"id":5914,"question":"هل يجوز لي شرعًا أن أقوم بتجهيز لوازم الدفن بالنيابة لزوجتي من دفن، وكفن، وخلافه؟","title":"حكم من قام بتجهيز لوازم دفن زوجته","answer":"الجواب: مؤنة التجهيز من مالها، إذا كان لها مال فمن مالها، فإن لم يكن لها مالها؛ فعلى وارثها، أنت والورثة،... يقوم بما يلزم من التجهيز، والكفن، والتغسيل، وحفر القبر، ونحو ذلك، وإذا كان لها مالها فتجهيزها من مالها يقدم على الورثة.","link":"https://binbaz.org.sa/fatwas/1236/حكم-من-قام-بتجهيز-لوازم-دفن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_233.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5995,"question":"هل ورد شيء في وقوف أهل الميت عن يمين الإمام، أو عن شماله عند الصلاة، أفتونا، جزاكم الله؟","title":"حكم الوقوف عن يمين الإمام في صلاة الجنازة","answer":"الجواب: لم يرد شيء في هذا، وإنما بعض الناس يقف؛ لأنه ما وجد مكانًا في الصف الأول، ويعجز أن يتأخر عن الصف الثاني، أو الثالث، فالذي نرى أنه لا يقف مع الإمام إلا من عجز ما وجد مكانًا، فإنه لا يصلي خلف الصف وحده. أما الذي معه غيره، فيصفون، ولو الصف ما تم، ولو صفًا قصيرًا، ولو ثلاثة، أربعة، يصفون جميعًا، ولو اثنين، يصفون جميعًا، ولا يصف مع الإمام، إنما يقف مع الإمام العاجز الذي ما وجد مكانًا إذا الصف تام، ولم يجد أحدًا يقف معه إلا هو؛ لا بأس أن يقف مع الإمام عن يمينه؛ حتى لا يصلي فردًا خلف الصف. أما الذي معه غيره فيصلي خلف الصف، أو جماعة مستقلين صفًا مستقلًا اثنين، أو ثلاثة،  أو أكثر. السؤال: ولا في أي فرض؟ الجواب: في جميع الفروض لا يصلي وحده، لا بد أن يجد فرجة في الصف، أو يتقدم عن يمين الإمام.","link":"https://binbaz.org.sa/fatwas/1371/حكم-الوقوف-عن-يمين-الامام-في-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_329.mp3","categories":["الصلاة على الميت"]},{"id":6163,"question":"قال العلماء إن الغسل من غسل الميت سنة، وليس بواجب، فهل الوضوء يجب على من غسل الميت، أم سنة كالغسل؟","title":"حكم الغسل والوضوء على من غسل ميتًا","answer":"الجواب: الغسل سنة، إذا غسل ميتًا السنة أن يغتسل، والوضوء أوجبه قوم، وليس عليه أدلة واضحة، لكن إن توضأ فحسن؛ خروجًا من الخلاف، وإن توضأ مع الغسل؛ فهو أكمل. لكن لا يجب الغسل، وإنما يستحب، أما الوضوء فالقول فيه قول أكثر جاء عن بعض الصحابة عن جابر، قيل: توضأ، فإذا توضأ مع الغسل؛ فهو أحوط، وأولى، لكن هذا إذا كان ما مس العورة. أما إذا مسه ويده مست عورة الميت؛ وجب عليه الوضوء بكل حال؛ لأن مس العورة ينقض الوضوء، ولا يمس العورة، فيجعل بينه وبين العورة شيئًا، خرقًا يغسل بها، وينظف بها، لكن لو قُدر أن يده أخطأت، ومست العورة وجب عليه الوضوء، أما إذا كان ما أصاب العورة؛ فالأولى له أن يتوضأ؛ خروجًا من الخلاف، وذلك طهارة، وخير كثير، والغسل سنة أيضًا.","link":"https://binbaz.org.sa/fatwas/1624/حكم-الغسل-والوضوء-على-من-غسل-ميتا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_515.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":6656,"question":"في واحد مات وهو يذبح للجن، فهل يصلى عليه، ويدعا له بالرحمة؟","title":"حكم الدعاء والترحم على من يذبح للجن بعد موته","answer":"الجواب: لا، هذا مشرك لا يصلي عليه، ولا يغسل، ولا يدفن مع المسلمين، الذي يذبح للجن، أو يدعو الأولياء، أو أهل القبور، يستغيث بهم، أو ينذر لهم، هذا الشرك الأكبر، هذا من دين الجاهلية، دين أبي جهل.","link":"https://binbaz.org.sa/fatwas/2527/حكم-الدعاء-والترحم-على-من-يذبح-للجن-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1022.mp3","categories":["الصلاة على الميت"]},{"id":6657,"question":"بالنسبة طيب الآن صلاة الجنازة يقف بعض المصلين مع الإمام من ناحية اليمين؟","title":"حكم وقوف بعض المصلين عن يمين الإمام","answer":"الجواب: هذا قد يظن أنه سنة فلا ينبغي أن يفعل؛ لأن فعل هذا قد يوهم بعض الناس أن الوقوف عن يمين الإمام سنة، وأن يقف مع أبي الميت، أو أخو الميت، أو زوج الميتة، أو نحو ذلك، هذا ما له أصل، وإنما يقف عن يمين الإمام؛ لأنهم ما لهم مكان، لكن إذا كان معه اثنين، ثلاثة يصفون صفًا خلف الناس.","link":"https://binbaz.org.sa/fatwas/2538/حكم-وقوف-بعض-المصلين-عن-يمين-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1033.mp3","categories":["الصلاة على الميت"]},{"id":6968,"question":"هل يجب على المصلين على الجنازة أن يكملوا الصف الأول، ثم الذي يليه، أم  السنة أن يكونوا ثلاثة صفوف، ولو أنها لم تكمل الصفوف الثلاثة؟","title":"حكم تكثير الصفوف في الصلاة على الجنازة","answer":"الجواب:\n\nأفتى بعض أصحاب النبي ﷺ فيما روي عنه أنها تكون ثلاثة صفوف، ولو لم تكمل، لكن إذا تيسر تكميلها؛ فهو أولى على الطريقة المعروفة في صلاة الفريضة، إذا تيسر التكميل؛ فهو أولى، وأفضل.\n\nالسؤال: يعني يا شيخ لو صفوا ثلاث صفوف صغار يجوز؟\n\nالجواب: أفتى به بعض الصحابة: مالك، وأبو هريرة أنه أفتى بذلك، ولكن كونه يكمل الصف الأول، ثم الثاني، وآخره إذا تيسر يكون أولى، لكن قد لا يتيسر هذا بسبب الهجل، وبسبب بعض كبار المساجد.\n\nالسؤال: أقصد يا شيخ أن الجماعة يكونون قليلًا ولو ينقسموا إلى ثلاثة صفوف جائز أو يكونون صفًا واحدًا؟\n\nالجواب: أفتى بهذا جمع من أهل العلم، ويروي عن بعض الصحابة، لكن إذا كان كملوا الصف الأول، ثم بدأوا في الثاني؛ يكون أفضل كما في الفرائض.","link":"https://binbaz.org.sa/fatwas/2925/حكم-تكثير-الصفوف-في-الصلاة-على-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1373.mp3","categories":["الصلاة على الميت"]},{"id":6995,"question":"هل يجب على المصلين على الجنازة أن يكملوا الصف الأول، ثم الذي يليه، أم  السنة أن يكونوا ثلاثة صفوف، ولو أنها لم تكمل الصفوف الثلاثة؟","title":"حكم تكثير الصفوف في الصلاة على الجنازة","answer":"الجواب:\n\nأفتى بعض أصحاب النبي ﷺ فيما روي عنه أنها تكون ثلاثة صفوف، ولو لم تكمل، لكن إذا تيسر تكميلها؛ فهو أولى على الطريقة المعروفة في صلاة الفريضة، إذا تيسر التكميل؛ فهو أولى، وأفضل.\n\nالسؤال: يعني يا شيخ لو صفوا ثلاث صفوف صغار يجوز؟\n\nالجواب: أفتى به بعض الصحابة: مالك، وأبو هريرة أنه أفتى بذلك، ولكن كونه يكمل الصف الأول، ثم الثاني، وآخره إذا تيسر يكون أولى، لكن قد لا يتيسر هذا بسبب الهجل، وبسبب بعض كبار المساجد.\n\nالسؤال: أقصد يا شيخ أن الجماعة يكونون قليلًا ولو ينقسموا إلى ثلاثة صفوف جائز أو يكونون صفًا واحدًا؟\n\nالجواب: أفتى بهذا جمع من أهل العلم، ويروي عن بعض الصحابة، لكن إذا كان كملوا الصف الأول، ثم بدأوا في الثاني؛ يكون أفضل كما في الفرائض.","link":"https://binbaz.org.sa/fatwas/2925/حكم-تكثير-الصفوف-في-الصلاة-على-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1373.mp3","categories":["الصلاة على الميت"]},{"id":7563,"question":"هذه الرسالة من نجران، يقول مرسلها: إنه يرى كثيرين يصلون على الجنازة أكثر من مرة، فما حكم الصلاة على الجنازة أكثر من مرة؟","title":"الصلاة على الجنازة أكثر من مرة","answer":"الجواب: ما نعلم فيها بأس إذا حضر الجنازة صلى عليها مع جماعة، ثم حضر جماعة وصلى معهم عليها في المقبرة أو في أي مكان لا حرج في ذلك إن شاء الله، لا بأس بذلك، الواجب مرة، الواجب أن يصلى عليها مرة واحدة، لكن لو قدر أنهم صلوا عليها في المسجد، ثم جاء آخرون وصلى معهم في المقبرة أو في مسجد آخر وحضر معهم وصلى لا بأس، كل هذا من مزيد الخير. نعم.","link":"https://binbaz.org.sa/fatwas/4568/الصلاة-على-الجنازة-اكثر-من-مرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01408.mp3","categories":["الصلاة على الميت"]},{"id":7572,"question":"هذه الرسالة وردت من البحرين، يقول مرسلها: أنا حامد محمد عبد الحميد من جمهورية مصر العربية ومقيم في دولة البحرين الشقيق، ومتابع لبرنامجكم نور على الدرب، وأنا مسرور منه جداً جداً لإجابته على أسئلة المستمعين، يقول: سمعت في البرنامج من فضيلة العلماء أن الطفل الذي يتوفى يصلى عليه، وأنا توفى مني أربعة أطفال لا يقل العمر عن سنة واحدة، ولم يصل عليهم لأنني مفوض الأمر لوالدي، أفيدوني أفادكم الله؟","title":"حكم الصلاة على الطفل المتوفى","answer":"الجواب: لاشك أن الطفل الصحيح أنه يصلى عليه، الطفل الصغير الرضيع يصلى عليه، هذا هو الصواب، وقال بعض أهل العلم لا يصلى عليه، ولكن الصواب أنه يصلى عليه، فإذا جهل الإنسان ودفنه ولم يصل عليه جهلاً منه فنرجو أن يعفو الله عنه وليس عليه شيء، لكن ينبغي له التنبه للمستقبل وأن لا يدفن حتى يصلى عليه، يغسل ويكفن ويصلى عليه كالكبير، يغسل يكفن ويطيب ويصلى عليه ثم يدفن كالكبار، هذا هو المشروع وهذا هو الواجب، وهذا هو الأرجح من قولي العلماء في الطفل الصغير. نعم.","link":"https://binbaz.org.sa/fatwas/4578/حكم-الصلاة-على-الطفل-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01608.mp3","categories":["الصلاة على الميت"]},{"id":7953,"question":"تقول أيضاً الأخت حرم يوسف محمد يوسف من السودان: إذا خرج المسلم من حدود الشريعة الإسلامية، هل ينبغي للمسلمين أن يصلوا عليه عند مماته أم لا؟","title":"حكم الصلاة على الكافر والعاصي","answer":"الجواب: هذا يختلف إن كان خروجه عن الحدود يوجب كفره صار مرتداً ولا يصلى عليه، أما إن كان خروجه بالمعصية مثل زنى وهو لا يستحل الزنا، أو شرب الخمر وهو لا يستحل الخمر، أو معصية أخرى لا يستحلها، هذا يصلى عليه ويدعى له بالمغفرة والرحمة؛ لأنه عاصي، أما إذا كانت معصيته توجب الردة تخرجه عن الإسلام هذا لا يصلى عليه، مثل ترك الصلاة والعياذ بالله وهو جاحد لوجوبها، مثل استحلال الزنا يراه حلال، مثل سب الدين وسب الرسول صلى الله عليه وسلم والاستهزاء بالرسول صلى الله عليه وسلم، الذي يموت على هذه الحال لا يصلى عليه؛ لأنها ردة عن الإسلام نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/5509/حكم-الصلاة-على-الكافر-والعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_069/06913.mp3","categories":["الصلاة على الميت"]},{"id":7956,"question":"تقول أيضاً الأخت حرم يوسف محمد يوسف من السودان: إذا خرج المسلم من حدود الشريعة الإسلامية، هل ينبغي للمسلمين أن يصلوا عليه عند مماته أم لا؟","title":"حكم الصلاة على الكافر والعاصي","answer":"الجواب: هذا يختلف إن كان خروجه عن الحدود يوجب كفره صار مرتداً ولا يصلى عليه، أما إن كان خروجه بالمعصية مثل زنى وهو لا يستحل الزنا، أو شرب الخمر وهو لا يستحل الخمر، أو معصية أخرى لا يستحلها، هذا يصلى عليه ويدعى له بالمغفرة والرحمة؛ لأنه عاصي، أما إذا كانت معصيته توجب الردة تخرجه عن الإسلام هذا لا يصلى عليه، مثل ترك الصلاة والعياذ بالله وهو جاحد لوجوبها، مثل استحلال الزنا يراه حلال، مثل سب الدين وسب الرسول صلى الله عليه وسلم والاستهزاء بالرسول صلى الله عليه وسلم، الذي يموت على هذه الحال لا يصلى عليه؛ لأنها ردة عن الإسلام نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/5509/حكم-الصلاة-على-الكافر-والعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_069/06913.mp3","categories":["الصلاة على الميت"]},{"id":8509,"question":"له سؤال ثالث يقول فيه: هل يجوز أن أصلي على قبر أبي صلاة الجنازة عند زيارته طلباً للرحمة، وهل إذا ورث الميت مصحفاً ينال أجراً عند تلاوة أبنائه فيه؟","title":"حكم الصلاة على الميت عند زيارة قبره","answer":"الجواب: إذا كنت قد صليت على أبيك مع الناس فلا حاجة إلى إعادة الصلاة، تزوره تدعو له فقط، تأتي المقبرة وتسلم على أهل القبور وتدعو لهم وتدعو لأبيك، كما قال النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية هذه السنة، فتسلم على أهل القبور، وعلى أبيك، وتدعو له بالمغفرة والرحمة، ولا حاجة إلى الصلاة، هذا إذا كنت قد صليت عليه، أما إذا كنت ما صليت عليه مع الناس فإنك تذهب إلى القبر وتصلي عليه في مدة شهر فأقل، إذا كان مضى له شهر أو أقل تصلي عليه، أما إذا طالت المدة فلا صلاة عند جمع من أهل العلم، والدعاء يكفي، الدعاء لأبيك والاستغفار له والترحم عليه والصدقة عنه بالمال، كل هذا ينفع الميت من أب وغيره.\nوأما المصحف إذا خلفه الميت فهو ينفعه، إذا وقفه جعله وقفاً ينفعه أجره، كما لو وقف كتباً للعلم كتب ... العلم المفيد علم الشرع أو علم مباح وانتفع به الناس يؤجر على ذلك؛ لأنه أعانهم على خير، كما لو وقف أرضاً أو بيتاً أو دكاناً يتصدق بغلته على الفقراء أو تعمر به المساجد، كل هذا يؤجر عليه، وقد قال عليه الصلاة والسلام في الحديث الصحيح: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له فالصدقات الجارية تنفع الميت إذا كان مسلم، تنفعه الصدقات الجارية، ينفعه دعاء أولاده ودعاء غيرهم، ينفعه الوقف الذي يوقف بعده من بيت أو أرض أو دكان أو نخيل أو أشباه ذلك، ينتفع بهذا الوقف إذا انتفع به الناس أكلوا من ثمرته وانتفعوا بثمرته، أو صرفت ثمرته في مساجد المسلمين في إصلاحها، في فرشها، في تنويرها إلى غير ذلك. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6587/حكم-الصلاة-على-الميت-عند-زيارة-قبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20304.mp3","categories":["الصلاة على الميت"]},{"id":8607,"question":"يسأل أيضاً ويقول: إذا اجتمعت جنائز رجل وامرأة وطفل، فأيهما يقدم إلى الإمام؟","title":"من يقدم عند اجتماع جنازة رجل وطفل وامرأة؟","answer":"الجواب: السنة أن يقدم إلى الإمام الرجل ثم الطفل الذكر، ثم المرأة، تكون إلى جهة القبلة المرأة، ويكون وسطها عند رأس الرجل حتى يكون موقف الإمام من الجميع موافقاً للسنة، فيوضع الرجل عند قرب الإمام، ثم يليه الطفل الذكر، ثم يليه المرأة، هذه السنة، تكون المرأة إلى جهة القبلة، والرجل يكون إلى جهة الإمام، ويكون وسط المرأة مساوياً لرأس الرجل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6744/من-يقدم-عند-اجتماع-جنازة-رجل-وطفل-وامراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21010.mp3","categories":["الصلاة على الميت"]},{"id":9400,"question":"يسأل أخونا أيضًا عن الذي يحكم عليه بالقصاص قتلًا هل يصلى عليه أو لا؟","title":"حكم الصلاة على من قتل قصاصًا من المسلمين","answer":"الجواب: نعم يصلى عليه، إذا كان مسلمًا يصلى عليه، ولو أنه فعل هذه الجريمة، والقصاص كفارة، وهكذا من زنى وهو محصن أو زنت وهي محصنة فقتل ... بالرجم يصلى عليه سواء كان ثبت عليه ذلك بالشهود أو بالإقرار، والنبي ﷺ صلى على ماعز الذي زنى وهو محصن، فأمر النبي ﷺ برجمه ثم صلى عليه، وصلى على الغامدية عليه الصلاة والسلام التي زنت وهي محصنة فأمر برجمها وصلى عليها عليه الصلاة والسلام؛ لأن إقرارهم وتوبتهم له شأن عظيم، التوبة يمحو الله بها الذنوب ثم الحد زيادة من أسباب الكفارة أيضًا.\nفالحاصل: أن من قتل بحق وهو مسلم يصلى عليه، القصاص حق، وإقامة الحدود حق فيصلى عليهم، وهكذا لو قتل إنسان ظلمًا من باب أولى أنه يصلى عليه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7565/حكم-الصلاة-على-من-قتل-قصاصا-من-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_188/18806.mp3","categories":["الصلاة على الميت"]},{"id":9491,"question":"هذه أول رسالة في البرنامج بعث بها الأخ صبري الجبوري من الجمهورية العراقية، تحتوي الرسالة على عدة أسئلة؛ السؤال الأول يقول فيه: أرجو أن تبينوا لنا ما حكم تارك الصلاة، وهل يجوز أن يصلى عليه إذا مات أفيدونا أفادكم الله؟","title":"حكم تارك الصلاة وهل يُصلى عليه إذا مات؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الصلاة عمود الإسلام، وهي أهم الفرائض وأعظم الواجبات بعد الشهادتين، وقد اختلف العلماء رحمهم الله في تاركها تهاونًا وكسلًا وهو يقر بوجوبها وأنها حق وأنها فرض ولكنه يتساهل في تركها، فذهب جمع من أهل العلم إلى أنه لا يكفر ولكن يكون قد أتى إثمًا عظيمًا ومعصية عظيمة أعظم من الزنا والسرقة، وأعظم من الربا واللواط وشبه ذلك.\nوذهب آخرون من أهل العلم إلى أنه يكفر بذلك كفرًا أكبر وهذا هو القول الصواب، وهو الحق أنه يكفر كفرًا أكبر لأدلة كثيرة؛ منها:\nقوله جل وعلا عن أهل النار لما سئلوا: مَا سَلَكَكُمْ فِي سَقَرَ ۝ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:42-43] فدل ذلك على أن من ترك الصلاة فليس من أهل الجنة بل هو من أهل النار.\nومنها قوله ﷺ: رأس الأمر الإسلام، وعموده الصلاة لما تترك العمود سقط ما عليه.\nومنها قوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه.\nوهذا كفر معرف بـ(أل) وشرك معرف بـ(أل)، وذلك يدل على أنه الكفر الأكبر والشرك الأكبر، خرجه مسلم في صحيحه.\nومنها ما رواه الإمام أحمد وأهل السنن بإسناد صحيح عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر في أدلة كثيرة أخرى.\nوعلى هذا لا يصلى عليه ولا يغسل ولا يكفن ولا يدفن في مقابر المسلمين بل يحفر له في أي جهة من الجهات ويدفن كما يدفن غيره من الكفرة حتى لا يتأذى الناس بنتنه وجيفته، هذا هو الصواب في هذه المسألة الخطيرة التي كثر فيها اليوم الكلام، وقل من يحافظ على الصلاة في الجماعة وفي وقتها إلا من هداه الله.\nوالمقصود أن ترك الصلاة أمر خطير، فإن كان عن جحد لوجوبها فهذا كافر بالإجماع، أما إن كان تهاونًا وكسلًا فالصواب أنه كافر كفرًا أكبر، وقد كثر كما تقدم من فعل هذا الأمر ومن تكاسل عن الصلاة فالواجب الحذر الواجب الحذر، الواجب على من يدعي الإسلام أن يتقي الله، وأن يحافظ على الصلاة في وقتها وأن يؤديها في الجماعة طاعة لله ورسوله، فإن الصلاة من حفظها حفظ دينه ومن ضيعها فهو لما سواها أضيع، نسأل الله السلامة. نعم.","link":"https://binbaz.org.sa/fatwas/7656/حكم-تارك-الصلاة-وهل-يصلى-عليه-اذا-مات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19301.mp3","categories":["الصلاة على الميت","حكم الصلاة وأهميتها"]},{"id":9836,"question":"نبدأ أولاً برسالة نعمان علي حسن مقيم في الرياض بجوار المعهد العلمي يسأل عن تارك الصلاة، يقول المستمع نعمان: رجل في قرية لا يصلي ولا يصوم ولا يقوم إلا بما يتنافى مع شريعتنا السمحاء مثل: السرقة، والمشاحنة بين المسلمين، فهل إذا مات يغسل ويكفن ويصلى عليه، نرجو توضيح موقف المسلمين من هذا الشخص، جزاكم الله خير الجزاء؟","title":"حكم الصلاة على من مات تاركاً للصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم على عبده ورسوله نبينا وإمامنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهده إلى يوم الدين.\nأما بعد: فقد دلت سنة رسول الله ﷺ على أن من ترك الصلاة فإنه كافر، ومعلوم أن الكافر لا يغسل ولا يصلى عليه ولا يدفن في مقابر المسلمين بل يجب أن يوارى في الأرض في محل آخر غير مقابر المسلمين؛ لئلا يؤذي الناس بنتنه وجيفته.\nفالحاصل: أن من كان لا يصلي ومعروف بهذا فإنه لا يصلى عليه ولا يغسل، وإذا كان مع ذلك لا يصوم ويؤذي المسلمين صار الشر أكثر، ولكن العمدة في كفره على تركه للصلاة نسأل الله العافية، ومن ذلك مما ورد في ذلك قوله عليه الصلاة والسلام بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، وقال عليه الصلاة والسلام العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأبو داود والترمذي والنسائي وابن ماجة بإسناد صحيح، وقال عليه الصلاة والسلام رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله هذه الأحاديث وما جاء في معناها كلها تدل على كفر تارك الصلاة نسأل الله العافية والسلامة، نعم.","link":"https://binbaz.org.sa/fatwas/8000/حكم-الصلاة-على-من-مات-تاركا-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_261/26101.mp3","categories":["حكم الصلاة وأهميتها","الصلاة على الميت"]},{"id":10237,"question":"ما هي كيفية الصلاة على الميت بالتفصيل؟ وهل يشترط فيها الطهارة؟","title":"كيفية صلاة جنازة","answer":"الجواب: نعم؛ صلاة الميت صلاة لابد لها من الطهارة؛ لأن الرسول سماها صلاة عليه الصلاة والسلام، فهي صلاة فيها افتتاح بالتكبير وفيها تسليم، فهي صلاة تجب لها الطهارة، تجب فيها قراءة الفاتحة، والدعاء للميت أيضًا، والصلاة على النبي ﷺ، فهي صلاة، فمن صلى بغير طهارة لم تصح صلاته.\nوالمشروع فيها: أن يكبر أولًا، ثم يقرأ الفاتحة وما تيسر معها، ثم يكبر ثانيًا ويصلي على النبي ﷺ مثلما يصلي في الصلاة الصلاة الإبراهيمية المعروفة: (اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد). ثم يكبر الثالثة ويدعو للميت يقول: (اللهم اغفر لحينا وميتنا وشاهدنا وغائبنا وصغيرنا وكبيرنا وذكرنا وأنثانا، اللهم من أحييته منا فأحيه على الإسلام، ومن توفيته منا فتوفه على الإيمان، ثم يقول: اللهم اغفر لفلان اللهم اغفر له وارحمه، أو اللهم اغفر لها -إن كانت مرأة- وارحمها، وإن سماهما باسمهما فحسن، اللهم اغفر لفلان بن فلان، اللهم اغفر لفلانة بنت فلان، اللهم اغفر لها وارحمها وعافها واعف عنها، وأكرم نزلها، ووسع مدخلها، واغسلها بالماء والثلج والبرد، ونقها من الخطايا كما ينقى الثوب الأبيض من الدنس، اللهم أبدلها دارًا خيرًا من دارها، وأهلًا خيرًا من أهلها، وأدخلها الجنة وأعذها من عذاب القبر ومن عذاب النار، وافسح لها في قبرها ونور لها فيه).\nوإن كان لها .. إن كان الرجل ميتًا له زوجة تقول: زوجة خير من زوجته، والمرأة كذلك زوجًا خيرًا من زوجها إذا كان لها زوج وإذا مات زوجها.. زوج خيرًا من زوجها، وإذا كانت الميتة امرأة ولها زوج قيل فيها كذلك، وهو يعرف أن لها زوج يقول: اللهم أبدله زوجة خيرًا منها، وإن زاد وقال: اللهم إن كان محسنًا فزد في إحسانه، وإن كان مسيئًا فتجاوز عن سيئاته أنت أهل الجود والفضل، اللهم لا تحرمنا أجره ولا تضلنا بعده واغفر لنا وله، كل هذا حسن، كله مشروع، وإن زاد بعض الدعوات كذلك، ثم يكبر الرابعة ويسكت قليلًا ثم يسلم تسليمة واحدة عن يمينه، هذا هو المشروع في صلاة الجنازة، أربع تكبيرات يرفع يده مع كل تكبيرة هذا هو الأفضل، ويقرأ بعد الأولى الفاتحة، والأفضل عدم الاستفتاح، وإن استفتح فلا حرج، ويقرأ مع الفاتحة سورة قصيرة أو بعض الآيات كما ثبت عن ابن عباس عن النبي صلى الله عليه وسلم، ثم يكبر الثانية ويصلي على النبي ﷺ مثلما يصلي في الصلاة كما تقدم، ثم يكبر الثالثة ويقول ما تقدم: (اللهم اغفر لحينا وميتنا وشاهدنا وغائبنا وصغيرنا وكبيرنا وذكرنا وأنثانا، هذا عام، اللهم من أحييته منا فأحيه على الإسلام، ومن توفيته منا فتوفه على الإيمان، اللهم اغفر له إن كان الميت ذكر، أو اللهم اغفر لها، أو يريد الميت اللهم اغفر له أو يريد الجنازة يقول: اللهم اغفر لها، كله جائز، وإذا عرفه قال: اللهم اغفر لفلان، أو عرفها وقال: اللهم اغفر لفلانة، كله طيب حسن، اللهم اغفر له وارحمه وعافه واعف عنه وأكرم نزله ووسع مدخله واغسله بالماء والثلج والبرد ونقه من الخطايا كما ينقى الثوب الأبيض من الدنس، اللهم أبدله دارًا خيرًا من داره وأهلًا خيرًا من أهله، اللهم أدخله الجنة وأعذه من عذاب القبر ومن عذاب النار، وافسح له في قبره ونور له فيه، اللهم إن كان محسنًا فزد في إحسانه، وإن كان مسيئًا فتجاوز عن سيئاته أنت أهل الجود والفضل، اللهم لا تحرمنا أجره ولا تضلنا بعده واغفر لنا وله)، هذا كله مشروع ويكفي بعضه، ثم يكبر الرابعة قائلًا: الله أكبر، ثم يسلم تسليمة واحدة عن يمينه بعدما يسكت قليلًا، هذا هو المشروع في صلاة الجنازة، والمشروع أن يرفع يديه مع كل تكبيرة هذا هو الأفضل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8406/كيفية-صلاة-جنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33510.mp3","categories":["الصلاة على الميت"]},{"id":10433,"question":"تسأل عن حكم صلاة الغائب بالنسبة للمرأة؟","title":"حكم صلاة الغائب للمرأة","answer":"الجواب: إذا صلى المسلمون على الغائب تصلي معهم، إذا صلى المسلمون على الغائب تصلي معهم أما تصلي وحدها على الغائب لا، لكن إذا حضرت مع الناس وصلى الإمام على الغائب تصلي معهم، والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8606/حكم-صلاة-الغاىب-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34109.mp3","categories":["الصلاة على الميت"]},{"id":10437,"question":"يقول: إذا وافق العيد الجمعة، فهل تصلى صلاة الجمعة؟","title":"حكم صلاة الجمعة إذا وافقت يوم عيد","answer":"الجواب: نعم، يصلي الإمام بالناس الحاضرين صلاة الجمعة، ومن حضر العيد لا تلزمه الجمعة، لكن إذا صلاها يكون أفضل له وخيراً له، وإلا فلا تلزمه يصلي ظهراً، من حضر العيد يصلي ظهراً إذا لم يحضر الجمعة، وإن حضر الجمعة كان أفضل، والإمام يقيم الجمعة ويصلي بمن حضر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8616/حكم-صلاة-الجمعة-اذا-وافقت-يوم-عيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31808.mp3","categories":["صلاة الجماعة","صلاة الجمعة","صلاة العيدين","الصلاة على الميت"]},{"id":10853,"question":"مستمع من الرياض رمز إلى اسمه بالحروف (م. ع. ح) يقول في أحد أسئلته: ما حكم الصلاة عند القبور، وهل ما يفعله البعض من القيام بصلاة الجنازة عند قبر الميت بعدما تفوته الصلاة عليها في المسجد، هل هذا العمل مشروع أم لا؟","title":"حكم الصلاة عند القبور، وحكم صلاة الجنازة عند القبر","answer":"الجواب: الصلاة عند القبور الصلاة ذات الركوع والسجود لا تجوز. المقدم: ذات الركوع والسجود؟  الشيخ: هذا لا يجوز، النبي ﷺ قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وكل قبر يصلى عنده فقد اتخذ مسجدًا، وإن لم يبن حوله مسجد، وقال -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد يعني: مصليات ألا فلا تتخذوها مساجد فإني أنهاكم عن ذلك رواه مسلم في الصحيح، وما ذاك إلا لأن الصلاة عندها وسيلة إلى عبادتها ودعائها، فلهذا لعن النبي ﷺ من فعل ذلك -عليه الصلاة والسلام- وحذر من ذلك، سدًا لذريعة الشرك حتى لا تكون الصلاة لهم بعد حين، قد يصلي لله، ثم يجره الشيطان إلى أن يصلي لهم، أو يدعوهم من دون الله، فلا تجوز الصلاة عند القبور لا فرضًا ولا نفلًا، ولا الجلوس عندها للدعاء، أو قراءة القرآن أو الصدقات، لا تتخذ محلًا لهذا، إنما تزار للذكرى والموعظة، لذكر الموت والموعظة والدعاء للمقبورين. أما أن يزورها لقصد آخر ليجلس عندها يدعو؛ لأنه يرى أنها أحرى بالإجابة، أو يجلس عندها يقرأ، أو يجلس عندها يصلي هذا لا أصل له، والصلاة أشد إذا صلى عندها أشد، الصلاة باطلة. أما صلاة الجنازة إذا صليت الجنازة إذا صلي على الجنازة عند القبور لا بأس، أو صلى على القبر ما حضر الصلاة في المسجد -مثلًا- وصلوا على قبر لا حرج في هذا، فعله النبي ﷺ، فإنه صلى على قبر بعدما دفن -عليه الصلاة والسلام- فلا حرج في ذلك، صلاة الجنازة لا حرج فيها، نعم. المقدم: بارك الله فيكم، إنما الكلام كما تفضلتم على الصلاة ذات الركوع، وذات السجود؟ الشيخ: هي الممنوعة في المقابر، نعم. المقدم: بارك الله فيكم ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/9022/حكم-الصلاة-عند-القبور-وحكم-صلاة-الجنازة-عند-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35603.mp3","categories":["الصلاة على الميت"]},{"id":11126,"question":"يسأل سؤالًا آخر فيقول: من كان يعرف عنه أنه لا يصلي في حياته، إلا أنه ختم حياته بالشهادتين عند احتضاره، هل يصلى عليه، أم أنه من الذين قال الله فيهم: وَلَيْسَتِ التَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ السَّيِّئَاتِ حَتَّى إِذَا حَضَرَ أَحَدَهُمُ الْمَوْتُ قَالَ إِنِّي تُبْتُ الآنَ [النساء:18]؟","title":"حكم الصلاة على من كان لا يصلي وختم حياته بالشهادتين","answer":"الجواب:  إذا لم يصرح بالتوبة ذكر الشهادة هو يقولها وهو حي الشهادة، هو يقولها وهو حي، والمنافقون يقولونها، فلا تنفعهم إذا لم يكن معها توبة من الكفر بالله، فإذا كان لا يصلي، أو يعرف أنه يسب الدين، أو أنه لا خير فيه، فكلمة الشهادتين ما تنفعه لا في حياته، ولا عند الموت، إلا إذا كان عن توبة فأمره إلى الله يوم القيامة، فظاهره الشر، فلا يصلى عليه، ولا يغسل، نسأل الله العافية. أما إذا قال: تبت إلى الله من عملي، وأنا كنت لا أصلي، وأنا أشهدكم أني تائب، أو صرح عندهم: إني تبت إلى الله من ترك الصلاة وكذا، ثم مات، فيكون حكمه حكم التائبين، نعم. المقدم: الله المستعان جزاكم الله خيرًا.  الشيخ: نسأل الله العافية.  المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/9305/حكم-الصلاة-على-من-كان-لا-يصلي-وختم-حياته-بالشهادتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36905.mp3","categories":["الصلاة على الميت"]},{"id":11160,"question":"إذا صليت صلاة الفجر في يوم العيد أو الجمعة، وبعد صلاتي أتوضأ مرة أخرى وأغتسل وأصلي صلاة حفظ الوضوء، فهل عملي هذا صحيح، ثم بعد ذلك أذهب إلى صلاة العيد، وأجلس أقرأ القرآن، ويوم الجمعة أصلي صلاة الضحى بينوا لنا ذلك مشكورين، جزاكم الله خيرًا؟","title":"حكم الاغتسال للجمعة وللعيدين","answer":"الجواب:  هذا طيب، الإنسان إذا أراد صلاة الجمعة فيغتسل سنة، أما صلاة العيد لم يرد فيها نص، ولكن إذا اغتسل فلا بأس؛ لأنها تشبه الجمعة من جهة أنها صلاة فيها اجتماع، لكن النص جاء في صلاة الجمعة، يستحب لها الغسل والوضوء عند قراءة القرآن أفضل، ولكن لا يجب الوضوء إلا إذا كان يقرأ من المصحف، أما إذا كان يقرأ عن ظهر قلب فليس بواجب الوضوء، له أن يقرأ وإن كان على حدث، إذا لم يكن جنبًا، أما الجنب فلا يقرأ حتى يغتسل. فالمقصود من هذا: أن القراءة عن طهارة أفضل وأولى، لكن لا تجب إلا إذا كان يقرأ من المصحف، أما إذا كان يقرأ عن ظهر قلب فلا حرج عليه أن يقرأ وإن كان على غير طهارة، إلا إذا كان جنبًا فليس له أن يقرأ حتى يغتسل، أما الحائض والنفساء اختلف فيهما العلماء -رحمة الله عليهم- هل هما كالجنب أم لا؟ والصواب أنهما ليستا كالجنب؛ لأن مدتهما تطول، فالأقرب أن لهما والأظهر أن لهما القراءة في غير المصحف عن ظهر قلب؛ حفظًا للوقت، وحرصًا على الفائدة العظيمة من قراءة القرآن، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9348/حكم-الاغتسال-للجمعة-وللعيدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37112.mp3","categories":["صلاة الجماعة","صلاة الجمعة","صلاة العيدين","الصلاة على الميت"]},{"id":12357,"question":"المستمع عبدالجليل عبدالله الحجاج من القطيف بعث يسأل ويقول: هل تجوز الصلاة على الميت بعد دفنه؟","title":"حكم الصلاة على الميت بعد دفنه","answer":"الجواب:  نعم، إذا كنت لم تصل عليه؛ تصلي عليه ولو بعد الدفن، وهكذا ... لم يصل عليه؛ تصلي عليه بعد الدفن إلى شهر تقريبًا، لا بأس، النبي ﷺ صلى على الميت بعد الدفن، وصلى على أم سعد بعد مضي شهر، فلا حرج في ذلك، بل هو سنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10556/حكم-الصلاة-على-الميت-بعد-دفنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39914.mp3","categories":["الصلاة على الميت"]},{"id":12948,"question":"على هذا التوجيه المبارك يا سماحة الشيخ، ننتقل إلى رسالة بعثت بها المستمعة صفاء من جمهورية مصر العربية، تقول السائلة: سماحة الشيخ! هل تجوز الصلاة على الميت وهو عليه دين؟","title":"حكم الصلاة على الميت الذي عليه دين","answer":"الجواب:  نعم، يصلى عليه وإن كان عليه دين، كان النبي ﷺ أول ترك ذلك، ثم صلى عليهم، وقضى ديونهم -عليه الصلاة والسلام-فيصلى عليه، وإن كان عليه دين، ويجتهد الورثة، أو الوصي في قضاء دينه، يجب على الورثة أن يبادروا بقضاء الدين ، أو الوصي إن كان له وصي أن يبادر بقضاء الدين، نعم.","link":"https://binbaz.org.sa/fatwas/11164/حكم-الصلاة-على-الميت-الذي-عليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50207.mp3","categories":["الصلاة على الميت"]},{"id":13249,"question":"هل الصحيح رفع اليدين في كل تكبيرة في صلاة الجنازة، أم يكبر بدون رفع اليدين، وكذلك في صلاة العيدين؟","title":"حكم رفع اليدين في تكبيرات صلاتي الجنازة والعيدين","answer":"الجواب:  الأفضل الرفع، وإن لم يرفع؛ فلا بأس، والأفضل الرفع؛ لأن الرسول ﷺ كان يرفع في تكبيرات الجنازة، ومثلها تكبيرات العيد، السنة الرفع؛ لأنها تكبير عن قيام، فأشبه تكبير الاستفتاح، وتكبير الركوع، يرفع في الصلوات كلها، إذا كبر رفع، وإذا كبر للركوع رفع، فالأفضل في التكبير للجنازة أن يرفع، وبعض أهل العلم قال: يرفع في الأولى فقط.  والصواب: أن الأفضل يرفع في الجميع في جميع تكبيرات الجنازة، وتكبيرات العيد. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11534/حكم-رفع-اليدين-في-تكبيرات-صلاتي-الجنازة-والعيدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51314.mp3","categories":["أصول الفقه","صلاة العيدين","الصلاة على الميت"]},{"id":13322,"question":"السائل من اليمن يقول في هذا  سماحة الشيخ إمام مسجدنا لا يأخذ بالقياس -أي: بقول العلماء- وإنما يأخذ بظاهر الحديث عن الرسول ﷺ مثل رفع اليدين عند التكبيرات في صلاة العيد وقال: لم يرد حديث عن الرسول ﷺ برفع يديه بالتكبيرات إنما العلماء استنبطوا ذلك وأخذوه بالقياس، مثل الرفع عند تكبيرة الإحرام في الصلوات الأخرى، ما رأيكم في صحة هذا القول؟ وهل يجوز أن نأخذ بقول العلماء، أم بظاهر الحديث مأجورين؟","title":"حكم رفع اليدين عند تكبيرات الجنازة والعيدين","answer":"الجواب: ثبت عن النبي ﷺ أنه كان يكبر أربع تكبيرات على الجنازة، فالسنة أن يكبر عليها أربع تكبيرات؛ في الأولى يقرأ الفاتحة، في الثانية يصلي على النبي ﷺ كما يصلي في الصلاة، في الثالثة يدعو للميت: اللهم اغفر لحينا وميتنا، وشاهدنا وغائبنا، وصغيرنا وكبيرنا، وذكرنا وأنثانا، اللهم من أحييته منا؛ فأحيه على الإسلام، ومن توفيته منا؛ فتوفه على الإيمان اللهم اغفر له، وارحمه، وعافه، واعف عنه، وأكرم نزله، ووسع مدخله، واغسله بالماء والثلج والبرد، ونقه من الخطايا كما ينقى الثوب الأبيض من الدنس، اللهم أبدله دارًا خيرًا من داره، وأهلًا خيرًا من أهله، اللهم أدخله الجنة، وأعذه من عذاب القبر، ومن عذاب النار كل هذا كان يدعو به النبي ﷺ للموتى، ثم يكبر الرابعة، ويسلم تسليمة واحدة. وكان يرفع يديه عند تكبيرة الإحرام في التكبيرة الأولى في الصلوات كلها، أما في الجنازة فقد ثبت عن ابن عمر أنه كان يرفع في التكبيرات كلها، قال بعض أهل العلم: وهذا يدل على أنه تلقاه عن النبي ﷺ؛ لأن هذا لا يقال من جهة الرأي، ففعل ابن عمر  ومن فعله من السلف يدل على أن هذا كان متوارثًا عندهم عن النبي -عليه الصلاة والسلام- لأن هذه المسائل لا تقال من جهة الرأي، فالأفضل في هذا هو الرفع في جميع التكبيرات؛ تكبيرات الجنازة.  وهكذا تكبيرات العيد في السبع الأولى والخمس الأخيرة في صلاة العيد، لما فعل ذلك بعض الصحابة دل ذلك على أنه من فعل النبي ﷺ؛ لأنه ليس من محلات الاجتهاد، بل هذا مما يتعلق بالرفع لأجل لا يتوهم فيه أنه من الرأي؛ لأنه لا مجال للرأي فيه، بل الظاهر حمله على أنه تلقاه عن النبي، عليه الصلاة والسلام. فالأفضل في هذا هو أنه يرفع يديه في جميع تكبيرات الجنازة، وفي جميع تكبيرات صلاة العيد، هذا هو الأفضل؛ كما فعل ذلك بعض السلف من الصحابة، كابن عمر، وغيره، والخلاف في هذا بحمد الله يسير، لكن هذا هو الأفضل. والعالم عليه أن يتحرى الحق من كتاب الله وسنة رسوله ﷺ هذا هو الواجب على أهل العلم أن يتحروا الحق من القرآن والسنة الصحيحة، ومما فعله أصحاب النبي ﷺ والسلف الصالح بعدهم، فإن الأدلة الشرعية في كتاب الله، وسنة رسوله ﷺ ثم إجماع سلف الأمة، ثم القياس الصحيح الذي تتوافر فيه الشروط. فالجمهور على أن القياس الصحيح الذي تتوافر فيه الشروط يعتمد إذا لم يوجد دليل من الكتاب والسنة والإجماع. وهذه المسائل مسائل عبادة تتلقى عن الرسول ﷺ وعن أصحابه ليست محل القياس، القياس في مسائل الأحكام في الفروع، أما العبادات فهي محل توقيف، ما هي محل قياس، إنما هي توقيفية عن الله، وعن رسوله، والصحابة إذا فعل الواحد منهم ما لا مجال للرأي فيه، وليس مما يتلقى عن الماضين؛ فإن هذا يكون له حكم الرفع؛ لأن الصحابة تلقوا دينهم، وتلقوا عباداتهم عن نبيهم -عليه الصلاة والسلام- فإذا لم يوجد نص من الكتاب، أو السنة، ولكن وجد من فعل الصحابة في المسائل التي لا مجال للرأي فيها، وليس الراوي لها ممن يتلقى عن الأمم الماضية؛ فإن هذا العمل يعطى حكم الرفع. نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11608/حكم-رفع-اليدين-عند-تكبيرات-الجنازة-والعيدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54104.mp3","categories":["صلاة العيدين","الصلاة على الميت"]},{"id":13480,"question":"رسالة وصلت إلى البرنامج من الجماهيرية الليبية وباعثها المستمع محمد علي شعبان، أخونا محمد يقول في أحد أسئلته: نحن نعمل في أحد الحقول النفطية بالصحراء، لدينا مسجد داخل الحقل، الحقل له بوابة واحدة، وأقرب منطقة عنده تقدر بحوالي أربعين كيلو مترًا، ليس هناك أحد مقيم داخل الحقل، أو خارجه بأسرته، وأطول مدة ممكن يقضيها أحدنا بالحقل أربعين يومًا تقريبًا، وليس لدينا إمام معين، و هل تصح في هذا المسجد صلاة العيد، وصلاة الجمعة؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الجمعة والعيدين على من يعمل في حقول النفط بالصحراء؟","answer":"الجواب: ما دام الحال كما ذكره السائل فليس عليكم جمعة ولا عيد؛ لأنكم لستم مستوطنين؛ إنما تقيمون أربعين يومًا، ثم ترجعون إلى أهليكم، فأنتم في هذه الحالة كسكان البادية تصلون ظهرًا أربعًا وعصرًا أربعًا وهكذا. وليس عليكم جمعة، ما دام الأمر كما ذكرتم ليس هناك سكان، وإنما هم العمال يعملون أكثر ما يعملون أربعين يومًا، ثم يرجعون إلى أهليهم، ويأتي غيرهم، فعليكم الصلوات الخمس أن تصلوها جماعة، يؤمكم أفضلكم وأقرؤكم، وإذا اخترتم واحدًا يؤمكم هو أقرؤكم كان ذلك أولى وأفضل، وليس عليكم جمعة، ولا عيد. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11783/حكم-الجمعة-والعيدين-على-من-يعمل-في-حقول-النفط-بالصحراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47809.mp3","categories":["صلاة الجماعة","صلاة الجمعة","صلاة العيدين","الصلاة على الميت"]},{"id":13495,"question":"السائل: عبدالله محمد يقول: هل تصح الصلاة خلف من عليه دين، مع أنه فقير، وحافظ للقرآن، ولم يأذنوا له أن يصلي يقولون له: بأنك عليك دين، هل تجوز الصلاة خلف هذا؟","title":"هل تصح الصلاة خلف المديون؟","answer":"الجواب:  نعم، تجوز الصلاة خلفه، ولو عليه دين، كان النبي ﷺ أولًا إذا أوتي بصاحب الدين قال: صلوا على صاحبكم ثم ترك ذلك، وكان يصلي عليهم وعليهم دين -عليه الصلاة والسلام- ويقضي عمن عليه دين إذا كان ما عنده وفاء، فهذا من كرم أخلاقه -عليه الصلاة والسلام- ومن جوده أنه إذا مات إنسان وعليه دين، وليس عنده شيء؛ قضى دينه، وصلى عليه، ونسخ هذا الأمر الذي فيه ترك الصلاة، فالذي عليه دين يصلى عليه، ويسعى لقضاء دينه بعد ذلك من ماله، أو غير ماله. المقصود: أن ترك الصلاة كان أولًا، ثم نسخ، وكان يصلي ﷺ على من عليه دين قبل الوفاء، اللهم صل عليه. نعم. المقدم: اللهم صل على نبينا محمد، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11801/هل-تصح-الصلاة-خلف-المديون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51809.mp3","categories":["الصلاة على الميت"]},{"id":13846,"question":"هذا سائل للبرنامج محمد عبدالله يقول في السؤال الأول: ما حكم الصلاة على الميت الغائب، علمًا بأنه قد صلي عليه في البلد الذي مات فيه؟","title":"حكم الصلاة على الميت الغائب","answer":"الجواب: الصلاة على الغائب فيها خلاف بين العلماء:\nمنهم من رآها خاصة بالنجاشي ، وأنه لا يصلى على الغائب؛ لأن الرسول ﷺ ما كان يصلي على الغائبين وإنما صلى على النجاشي خاصة.\nوذهب بعض أهل العلم: إلى أنه يصلى على الغائب إذا كان من له قدم في الإسلام كـالنجاشي من علماء أهل السنة وأمراء الحق الذين يدعون إلى الله ويعلمون الناس دين الله ولهم مواقف حميدة في نصر الدين تشبيهاً لهم بـالنجاشي .\nوالأمر في هذا واسع إن شاء الله، والقول: بأنه خاص بـالنجاشي قول قوي؛ لأن الرسول ﷺ لم يحفظ عنه أنه صلى على غير النجاشي، ولو كانت الصلاة على الغائب سنة لصلى على كثير من الناس؛ لأنه مات في زمانه جم غفير في مكة وغيرها، ولم يحفظ أنه صلى على أحد.\nفالأحوط تركها على الغائب، إلا إذا كان إنسانًا له قدم في الإسلام كما كان للنجاشي فلا مانع إن شاء الله من الصلاة عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12222/حكم-الصلاة-على-الميت-الغاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53720.mp3","categories":["الصلاة على الميت"]},{"id":14173,"question":"يقول السائل: يفوتني أحيانًا في صلاة الجنازة تكبيرة أو أكثر، حيث لا أدرك إلا الثالثة التي يدعى فيها للميت ثم أسلم بعد ذلك مع الإمام، فهل يجوز ذلك أم لابد من أداء التكبيرات التي فاتتني؟","title":"مشروعية قضاء التكبيرات الفائتة من صلاة الجنازة","answer":"الجواب: المشروع لك أن تؤدي التكبيرات، لقوله ﷺ: ما أدركتم فصلوا وما فاتكم فأتموا يعم صلاة الجنازة وغيرها، فإذا أدركت الثالثة فهي أول صلاتك، إذا كبرت تقرأ الفاتحة وما تيسر معها، ثم إذا كبر الرابعة صليت على النبي ﷺ، ثم إذا سلم كبرت وقلت: اللهم اغفر للميت. تدعو له بالمغفرة بكلمات قليلة ثم تكبر وتسلم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12614/مشروعية-قضاء-التكبيرات-الفاىتة-من-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54708.mp3","categories":["الصلاة على الميت"]},{"id":14174,"question":"هذا سائل للبرنامج حامد من الأردن الكرك يقول في هذا  هل تجوز الصلاة على من مات ولم يصل؟ وما معنى الحديث: صلوا على من مات من أهل القبلة هل هم المصلون الذين يتوجهون للقبلة؟ أم هذا الحديث عام لكل المسلمين الموحدين؟","title":"حكم صلاة الجنازة على تارك الصلاة","answer":"الجواب: من مات وهو لا يصلي لا يصلى عليه؛ لأن ترك الصلاة كفر والعياذ بالله، لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة أخرجه مسلم في صحيحه؛ ولقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر أخرجه الإمام أحمد وأهل السنن الأربع بإسناد صحيح.\nأما حديث: صلوا على أهل القبلة أو صلوا على من قال: لا إله إلا الله فهي أحاديث ضعيفة ولو صحت لكان المراد يعني: صلوا على من كان مسلمًا يقول: لا إله إلا الله ويلتزم بها ولا يأتي بمكفر كسائر الأحاديث التي في فضل لا إله إلا الله.\nالمراد إذا قالها مع أداء حقها والالتزام بما يحفظ عليه إسلامه، ولهذا في الأحاديث الصحيحة: إلا بحقها، إلا بحق الإسلام، فمن قالها ونقضها بكفره وضلاله ما تنفعه، كالمنافقين يقولون: لا إله إلا الله وهم في الدرك الأسفل من النار؛ لأنهم نقضوها بكفرهم وضلالهم، فالذي يقول: لا إله إلا الله، وهو يدعو البدوي أو يدعو الحسين أو يدعو عليًا  أو يدعو الشيخ عبد القادر أو يستغيث بالنبي ﷺ أو غيره هذا كفر ما تنفعه لا إله إلا الله، تنفع لا إله إلا الله من قالها وأدى حقها واستقام على دين الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12615/حكم-صلاة-الجنازة-على-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54709.mp3","categories":["الصلاة على الميت","الحكم على الأحاديث"]},{"id":14182,"question":"السائلة التي رمزت لاسمها بـ (م. ع) من حائل تقول: أسأل عن حكم صلاة المرأة على الميت سماحة الشيخ؟","title":"حكم صلاة المرأة على الميت","answer":"الجواب: مثل الرجل يشرع لها الصلاة على الميت مثل الرجل تصلي مع الناس في المساجد في المصلى على الموتى، أو في البيت على.. تصلي مع أهل البيت على الميت، لكن لا تتبع للمقبرة، الرسول ﷺ نهى عن اتباع الجنائز للموتى، نهى المرأة أن تتبع الجنائز وأن تزور القبور. أما الصلاة على الميت فهي مشروعة للجميع للرجل والمرأة سويًا سواء في المسجد أو في المصلى أو في بيته تصلي عليه مع أهله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12625/حكم-صلاة-المراة-على-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54717.mp3","categories":["الصلاة على الميت","قضايا المرأة"]},{"id":14219,"question":"في آخر أسئلته يقول هذا السائل: ما حكم الصلاة على الميت الغائب هل يجوز أن يصلى على إنسان غائب؛ لأن البعض يحتج بأن الصلاة على الغائب خاصة بالرسول عليه الصلاة والسلام عندما صلى على النجاشي؟","title":"هل يجوز أن يصلى على إنسان غائب؟","answer":"الجواب: هذا محل خلاف بين أهل العلم، وليس هناك شيء واضح في الحكم، لكن إذا صلي على من له قدم في الإسلام كأمير صالح، وعالم له أثره في الإسلام صلاة الغائب فلا حرج إن شاء الله؛ لأن الرسول ﷺ صلى على النجاشي لما حصل من الخير على يديه في إيوائه الصحابة ونصره للحق، ثم دخل في الإسلام فلهذا صلى عليه النبي ﷺ لما بلغه وفاته، وقال: صلوا على صاحبكم ولم يحفظ عنه ﷺ أنه صلى على غيره من الناس مع كثرة الموتى في مكة وغيرها، فلهذا احتج جمع من أهل العلم على أنه لا يصلى على الغائب وأن هذا خاص بالنبي ﷺ و بالنجاشي.\nوقال بعض أهل العلم: يصلى على الغائب وأن الأصل عدم الخصوصية، لكن من كان مثل النجاشي، عالم له أثره في الإسلام، أمير له أثره في الإسلام ومنفعة المسلمين ما هو على كل أحد، فهذا له وجهه، والأحوط ترك ذلك؛ لأن الرسول ﷺ لم يفعله مع الموتى الكثيرين عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12671/هل-يجوز-ان-يصلى-على-انسان-غاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54820.mp3","categories":["الصلاة على الميت"]},{"id":14395,"question":"كيف نصلي على الميت؟ وما هي الأدعية المأثورة؟","title":"صفة صلاة الجنازة","answer":"الجواب: يصلي عليه أربعًا، أربع تكبيرات، وأنت واقف، تصلي عليه مع إمامك، تكبر أربع تكبيرات، تقرأ بعد الأولى الفاتحة، الحَمْدُ للهِ رَبّ العَالَمِينَ، [الفاتحة:1] وما تيسر معها من آيات أو سور قصيرة، ثم تكبر وتصلي على النبي ﷺ كما تصلي في الصلاة، ثم تكبر الثالثة وتدعو للميت، بما يسر الله، ومنها: اللهم اغفر لحينا وميتنا، وشاهدنا وغائبنا، وصغيرنا وكبيرنا، وذكرنا وأنثانا، اللهم من أحييته منا فأحيه على الإسلام، ومن توفيته منا فتوفه على الإيمان، اللهم اغفر له وارحمه، وعافه واعف عنه، وأكرم نزله، ووسع مدخله، واغسله بالماء والثلج والبرد، ونقه من الخطايا كما ينقى الثوب الأبيض من الدنس، اللهم أبدله دارًا خيرًا من داره، وأهلًا خيرًا من أهله، اللهم أدخله الجنة، وأعذه من عذاب القبر، ومن عذاب النار، ووسع له في قبره، ونور له فيه منها: اللهم لا تحرمنا أجره، ولا تضلنا بعده، إلى غير هذا مما ورد، يدعو الإنسان بهذا، وما أشبهه مما ورد من الدعوات الطيبة، ثم يكبر الرابعة ويسلم عن يمينه، يكبر الرابعة ويسكت قليلًا، ثم يقول: السلام عليكم ورحمة الله عن يمينه، هذه الصفة الشرعية لصلاة الجنازة. هذا إذا تيسر له ذلك، أما إذا فاتته فليس عليه قضاء؛ لأنها فرض كفاية إذا قام بها من يكفي سقط عن الباقين، سقط عن الباقين، لكن إذا أدركها الحمد لله، وإلا أجزأ من فعلها من الإخوة وكفى، وإن أدرك بعضها صلى ما أدرك، وقضى ما فات كبقية الصلوات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12877/صفة-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48803.mp3","categories":["الصلاة على الميت"]},{"id":14922,"question":"المستمع: محمد عبدالله الغامدي، من الدمام، بعث رسالة ضمنها أربعة أسئلة، يسأل في سؤاله الأول يقول: بم تدرك الركعة، الجماعة، الجمعة، صلاة العيد، صلاة الجنازة؟","title":"بم تدرك صلاة الجمعة والجماعة والعيد والجنازة؟","answer":"الجواب: أما صلاة العيد، وصلاة الجمعة، وصلوات الأوقات الخمسة؛ تدرك بركعة، كما قال النبي ﷺ: من أدرك ركعةً من الصلاة فقد أدرك الصلاة والحديث الثاني: من أدرك ركعةً من الجمعة؛ فليضف إليها أخرى، وقد تمت صلاته. أما إذا أدرك أقل من ركعة؛ فإنه لا يدرك الجمعة، يصلي ظهرًا، ولا يدرك فضل الجماعة بذلك، إلا أن يكون معذورًا بمرض، أو شيءٍ آخر حال بينه وبين الحضور للجماعة، بغير اختياره، فله فضل الجماعة لعذره الشرعي، كما قال النبي ﷺ: من مرض أو سافر كتب الله له ما كان يعمل وهو صحيح مقيم يعني: بسبب العذر، وقال -عليه الصلاة والسلام- في غزوة تبوك: إن في المدينة أقوامًا ما سرتم مسيرًا، ولا قطعتم واديًا إلا وهم معكم قالوا: وهم في المدينة؟ قال: وهم في المدينة، حبسهم العذر وفي اللفظ الآخر: إلا شركوكم في الأجر فالمعذور حكمه حكم الحاضر في الأجر. أما إن كان تساهل وفرط، فإنه يفوته فضل الجماعة، وعليه أن يصلي في بيته، أو في المسجد الصلاة التي فاتته، نعم. أما الجنازة فتدرك ولو بالتكبيرة الأخيرة، إذا أدرك التكبيرة الأخيرة يكبرها، ويقرأ الفاتحة، ثم يكبر، ويصلي على النبي، وهو مستعجل، اللهم صل على رسول الله، ثم يكبر ويقول: اللهم اغفر له، ثم يكبر ويسلم، قبل أن ترفع بسرعة، نعم. المقدم: جزاكم الله خيرًا، والركعة بم تدرك لو تكرمتم؟ الشيخ: بالركوع، إذا أدرك الركوع فقد أدرك الركعة، وسقطت عنه الفاتحة؛ لأنه لم يدرك القيام، ويدل على هذا أنه ﷺ لما دخل أبو بكرة، وهو راكع -عليه الصلاة والسلام- ركع دون الصف، ثم دخل في الصف، فلما سلم النبي ﷺ قال له: زادك الله حرصًا، ولا تعد لا تعد للركوع دون الصف، يعني: ولم يأمره بقضاء الركعة، اللهم صل عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13415/بم-تدرك-صلاة-الجمعة-والجماعة-والعيد-والجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64005.mp3","categories":["أصول الفقه","صلاة العيدين","الصلاة على الميت"]},{"id":15045,"question":"أحمد صالح النعيم من جدة، جامعة الملك عبدالعزيز ، يقول: سؤالي هو عن كيفية غسل النبي ﷺ، أو تكفينه والصلاة عليه ودفنه، وفقكم الله؟","title":"كيفية غسل النبي ﷺ وتكفينه والصلاة عليه","answer":"الجواب: الرسول ﷺ غسل في ثيابه، فإنهم سمعوا مناديًا، الصحابة لما اختلفوا هل يجردونه أم لا؟ سمعوا مناديًا من داخل البيت يقول: أن غسلوا رسول الله في ثيابه، فغسلوه بثيابه، وصبوا الماء عليه، وغسلوه في ثيابه -عليه الصلاة والسلام-، ثم كفنوه في ثلاثة أثواب بيض سحولية من كرسف، يعني: من قطن، ليس فيها قميص، ولا عمامة، كما جاء في حديث عائشة -رضي الله عنها-، ثم صلى عليه الناس -عليه الصلاة والسلام- فرادى، ما أمهم عليه إمام بل صلى عليه الناس، كل يدخل ويصلي عليه في المسجد -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/13574/كيفية-غسل-النبي-ﷺ-وتكفينه-والصلاة-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65407.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":15188,"question":"أيضًا يقول في رسالته يسأل عن الصلاة على الميت يقول: هل يجوز إذا وقف الإمام لكي يصلي على الميت هل يجوز أن يصف الناس عن يمينه وشماله أم لا بد أن يكون جميع المصلين عن يمينه؟","title":"كيفية صف المصلين في صلاة الجنازة","answer":"الجواب: السنة دلت على أن المصلين يكونوا خلف الإمام، إذا زادوا عن واحد، فالسنة أن يكونوا خلف الإمام، هذا هو المعروف عن النبي ﷺ، ولما صف عن يمينه وشماله جابر وجبار أخرهما، وجعلهما خلفه -عليه الصلاة والسلام-، ولم يسمح أن يصلي عن يمينه إلا واحد؛ لما صف معه أنس وابن عباس، أنس في بعض الروايات في بيت جدته، وفي حديث ابن عباس في صلاة الليل، أما الاثنان فأكثر فيكونوا خلف الإمام، هذا السنة، نعم. صلاة الجنازة وغيرها.\nالمقدم: الملاحظ الآن أنه في المساجد إذا أتي بجنازة أنهم يصفون كثيرًا عن يمين الإمام، مع أن المسجد مليئًا بالمصلين؟\nالشيخ: لا، ينبغي أن يكونوا صفًا خلفه، ولو غير تام، أو يصفوا وراء الصف الأول أو الصف الثاني أو يصفوا وراء قدام الصف الأول، لكن يكونوا صفًا قصيرًا لا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/13690/كيفية-صف-المصلين-في-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_666/nour_66605.mp3","categories":["الصلاة على الميت"]},{"id":15203,"question":"له سؤال آخر لا يتعلق بالصوم، يقول: وجدنا شخصًا ميتًا معلقًا في شجرة، وفي عنقه حبل، ولا ندري هل قتل نفسه بالخنق أم علقه أحد بعد أن قتله، فإذا كان هو الذي علق نفسه بالحبل في الشجرة لكي يموت فهل يصلي عليه المسلمون أم لا؟","title":"حكم الصلاة على قاتل نفسه","answer":"الجواب: هذا إذا كان مسلمًا فإنه يصلى عليه، سواء كان قتل نفسه، أو قتله غيره يصلى عليه، وإن كان قد أتى جريمة عظيمة إذا كان قتل نفسه بالخنق فقد أتى جريمة عظيمة؛ لأن المسلم ليس له أن يقتل نفسه، الله -جل وعلا- حرم على الناس أن يقتلوا أنفسهم، قال سبحانه: وَلا تَقْتُلُوا أَنفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا [النساء:29] وقال النبي ﷺ: من قتل نفسه بشيء عذب به يوم القيامة لكن لو علم أنه قتل نفسه، فإنه يكون قد أخطأ، وأتى جريمة.  وأما الصلاة فيصلى عليه؛ لأن المعصية لا تمنع من الصلاة عليه، يصلي عليه بعض المسلمين، ويغسلونه، يغسلونه أولًا ويكفنونه، ثم يصلى عليه، ثم يدفن في مقابر المسلمين. وهكذا لو علم أنه مقتول قتله غيره ظلمًا، فإنه يغسل، ويصلى عليه، يغسل ويكفن ويصلى عليه، ويدفن في مقابر المسلمين، والله المستعان، لا حول ولا قوة إلا بالله، نعم.","link":"https://binbaz.org.sa/fatwas/13700/حكم-الصلاة-على-قاتل-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_671/nour_67105.mp3","categories":["الصلاة على الميت"]},{"id":15229,"question":"وردتنا رسالة من المستمع (م. م. ح) من رضوان بسوريا، يقول: هل يجوز الصلاة على الجنازة في المقبرة؟","title":"حكم الصلاة على الجنازة في المقبرة","answer":"الجواب:  نعم، الجنائز يصلى عليها في المساجد والمصليات وفي المقابر، لا حرج في ذلك، ربما صلى النبي ﷺ على الجنازة في المسجد، وربما صلى عليها في المصلى، وكان يصلي على القبر، والصلاة على القبر من جنس الصلاة على الجنازة، فإذا أحضروها في المقبرة، وصلوا عليها، فلا بأس، وإن كانت قد دفنت صلي على القبر، نعم.","link":"https://binbaz.org.sa/fatwas/13733/حكم-الصلاة-على-الجنازة-في-المقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_673/nour_67302.mp3","categories":["الصلاة على الميت"]},{"id":15236,"question":"أيضًا يقول في رسالته: هل يجوز الصلاة على الجنازة في المقبرة أم لا؟","title":"حكم الصلاة على الجنازة في المقبرة","answer":"الجواب:  لا حرج يصلى عليها في المقبرة، ويصلى على القبر، النبي ﷺ صلى على القبر في المقبرة؛ لما فاته الصلاة عليه في المسجد صلى عليه في المقبرة -عليه الصلاة والسلام-، والصلاة على الجنازة في المقبرة مثل الصلاة على القبر سواء سواء، فإذا فاتته الصلاة عليه في المصلى، وجاء إلى المقبرة وهو موجود ما بعد دفن، فلا بأس أن يصلي عليه، هو لم يصل عليه في المقبرة.  وإن شاؤوا أخروا ذلك حتى يدفن، ثم صلوا على قبره، كل هذا بحمد الله موسع، ولا حرج في ذلك، نعم. المقدم: شكرًا، أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13730/حكم-الصلاة-على-الجنازة-في-المقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_668/nour_66808.mp3","categories":["الصلاة على الميت"]},{"id":15437,"question":"هذا السائل يقول: إذا دخلت وهم يصلون على جنازة، هل أدخل معهم في صلاة الجنازة، أم أبدأ بصلاة الفرض، مع أنني لم أصل معهم الفرض؟","title":"حكم من دخل والناس يصلون الجنازة ولم يصل الفرض","answer":"الجواب: تبدأ بالجنازة؛ لأنها تفوت، والفرض يمكن أن تصلي بعد ذلك، تبدأ بالجنازة، ثم بعد ذلك تصلي الفرض، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13951/حكم-من-دخل-والناس-يصلون-الجنازة-ولم-يصل-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50012.mp3","categories":["الصلاة على الميت"]},{"id":15490,"question":"هذا سؤال أيضًا عن صفة صلاة الجنازة، وحكمها، وهل تشرع أيضًا للنساء كما هي للرجال؟","title":"صفة صلاة الجنازة وحكمها للرجال والنساء","answer":"الجواب: صلاة الجنازة مشروعة للجميع للرجال والنساء، وهي فرض كفاية، إذا قام بها واحد كفى وأجزأت، لكن السنة أن يصلي عليها الجم الغفير، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: ما من مسلم يصلي عليه أربعون رجلًا لا يشركون بالله شيئًا إلا شفعهم الله فيه وفي لفظ آخر يقول ﷺ: ما من رجل مسلم يصلي عليه أمة من الناس يبلغون المائة كلهم يشفعون فيه إلا شفعهم الله فيه أو كما قال -عليه الصلاة والسلام-، فكلما زاد الجمع صار خيرًا له، يدعون له، ويترحمون عليه. وصفتها أن الإمام يكبر أربع تكبيرات. \nيقف عند رأس الرجل، وعند وسط المرأة، أما قول بعض الفقهاء: عند صدر الرجل، فهو قول ضعيف لا أساس له، وإنما السنة أن يقف عند رأس الرجل، وعند وسط المرأة، هذا ما جاءت به السنة في حديث سمرة بن جندب في الوقوف وسط المرأة، ومن حديث أنس في الوقوف عند رأس الرجل، وعجيزة المرأة. فالسنة الثابتة عن رسول الله ﷺ تدل على أنه يقف الإمام عند رأس الرجل، وعند وسط المرأة، ثم يكبر يقول: الله أكبر، ثم يقرأ الفاتحة، يتعوذ بالله من الشيطان، ويسمي، ويقرأ الفاتحة.\nوليس فيها استفتاح على الأرجح؛ لأنها مبنية على التخفيف.\nالمقدم: القراءة سرًا؟ نعم.\nالشيخ: يقرأ التعوذ بالله من الشيطان الرجيم، ويسمي، ويقرأ سرًا الفاتحة، وإن جهر بعض الشيء حتى يعلم من ورائه أنه يقرأ، وحتى يستفيدوا بعض الأحيان يكون حسن، كما فعل ابن عباس للتعليم، ويقرأ سورة مع الفاتحة قصيرة لما جاء في الأحاديث الكثيرة عن النبي ﷺ أنه قال: لا صلاة لمن لم يقرأ بفاتحة الكتاب فصاعدًا يعني: فأكثر، فإذا قرأ سورة زيادة، وجاء في بعض الروايات أنه ﷺ قرأ بالفاتحة وسورة، فهذا أفضل، وإن اقتصر على الفاتحة كفى، وإذا قرأ معها بالعصر، ومثل قُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1] وأشباه ذلك، كان حسنًا حتى يجمع بين الفاتحة وزيادة. ثم يكبر الثانية يقول: الله أكبر، ويصلي على النبي ﷺ مثلما يصلي في الصلاة: اللهم صل على محمد وعلى آل محمد، كما صليت على آل إبراهيم، وبارك على محمد، وعلى آل محمد، كما باركت على آل إبراهيم في العالمين إنك حميد مجيد والمقصود أنه يصلي على النبي ﷺ مثل ما يصلي في الصلاة. ثم يكبر الثالثة ويدعو للميت، ويأتي بالأذكار الشرعية، بالدعوات الشرعية: اللهم اغفر لحينا وميتنا وشاهدنا وغائبنا وصغيرنا وكبيرنا، وذكرنا وأنثانا، اللهم من أحييته منا فأحيه على الإسلام، ومن توفيته منا فتوفه على الإيمان.\nاللهم اغفر له وارحمه، وعافه واعف عنه، وأكرم نزله ووسع مدخله، واغسله بالماء والثلج والبرد، ونقه من الخطايا كما ينقى الثوب الأبيض من الدنس، اللهم أبدله دارًا خيرًا من داره، وأهلًا خيرًا من أهله، اللهم أدخله الجنة وأعذه من عذاب القبر، ومن عذاب النار وسع له في قبره، ونور له فيه اللهم لا تحرمنا أجره، ولا تضلنا بعده، واغفر لنا وله.\nوإن زاد دعوات مثل: اللهم إن كان محسنًا فزد في إحسانه، وإن كان مسيئًا تجاوز عن سيئاته، أو قال: اللهم اغفر له وثبته بالقول الثابت، أو ما أشبه ذلك من الدعوات الطيبة، كله حسن. ثم يكبر الرابعة، ويسكت قليلًا؛ لأن هذا جاء في بعض الروايات عن النبي ﷺ وسلم، ثم يسلم تسليمة واحدة، هذا هو المحفوظ عن أصحاب النبي ﷺ على هذا الوجه. الشريعة عامة للنساء والرجال في الصلاة؛ لكن الخروج مع الجنازة إلى المقبرة هذا خاص بالرجال، وهكذا زيارة القبور خاص بالرجال، وقد قال -عليه الصلاة والسلام-: من شهد الجنازة حتى يصلى عليها فله قيراط، ومن شهدها حتى تدفن له قيراطان قيل: يا رسول الله، ما القيراطان؟ قال: مثل الجبلين العظيمين وهذا يدل على فضل عظيم، وقال أيضًا -عليه الصلاة والسلام-: من تبع جنازة مسلم إيمانًا واحتسابًا، وكان معها حتى يصلى عليها، ويفرغ من دفنها، فإنه يرجع بقيراطين، كل قيراط مثل جبل أحد وهذا فضل عظيم. والخروج مع الجنائز فيه جبر للمصابين، وتعزية لهم، ومواساة لهم، فإنه إذا خرج معهم جبر قلوبهم، وعزاهم بعمله وقوله جميعًا، ولهذا شرع الله الصلاة على الموتى، واتباع الجنائز لهذه الفوائد الكثيرة، للإحسان إلى الميت والدعاء له، ولجبر المصابين ومواساتهم؛ ولتذكر الموت، وما يكون بعد الموت من العجائب والأهوال والأخطار، حتى يستعد المؤمن للموت وما بعده.\nنسأل الله للجميع العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خير الجزاء، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14025/صفة-صلاة-الجنازة-وحكمها-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_690/nour_69005.mp3","categories":["الصلاة على الميت","قضايا المرأة"]},{"id":15616,"question":"هل لصلاة الجنازة تسليمة واحدة فقط؟","title":"عدد تسليمات صلاة الجنازة","answer":"الجواب: هذا هو السنة، تسليمة واحدة، هذا هو الثابت عن أصحاب النبي ﷺ تسليمة واحدة، نعم؛ عن اليمين.","link":"https://binbaz.org.sa/fatwas/14156/عدد-تسليمات-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57104.mp3","categories":["الصلاة على الميت"]},{"id":15678,"question":"بعد هذا رسالة يقول صاحبها الراسل مقيم في المملكة، يسأل سماحتكم فيقول: كيف كانت صلاة النبي ﷺ حين صلى على المرأة التي كانت تقم المسجد بعد دفنها؟ فهل وضع القبر بين يديه كما توضع الجنازة؟جزاكم الله خيرًا.","title":"كيفية صلاة الجنازة على الميت في القبر","answer":"الجواب: نعم، صلى عليها مثلما يصلي على الجنائز، صلى عليها جعلها أمامه، وصلى حذاء وسطها، ودعا لها، كصلاة الجنازة سواء سواء.....، الميت يصلى عليه قبل الدفن، وبعد الدفن، فإذا ما صلي عليه قبل الدفن؛ صلي عليه بعد الدفن، فالرجل يوقف عند رأسه، والمرأة عند وسطها، كما لو كانت بارزة على وجه الأرض، وهكذا فعل النبي ﷺ مع الخادمة التي كانت تقم المسجد، صلى على قبرها -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14222/كيفية-صلاة-الجنازة-على-الميت-في-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70609.mp3","categories":["الصلاة على الميت"]},{"id":15934,"question":"ما هو الدعاء الذي يقال في الصلاة عند صلاتنا على الميت؟","title":"الدعاء الذي يقال في صلاة الجنازة","answer":"الجواب: أولًا: عند الدعاء يقول -بعد التكبيرة الثالثة-: اللهم! اغفر لحينا وميتنا، وشاهدنا وغائبنا، وصغيرنا وكبيرنا، وذكرنا وأنثانا، اللهم من أحييته منا فأحيه على الإسلام، ومن توفيته منا فتوفه على الإيمان هذا عام في كل جنازة، ثم بعد هذا يقول: اللهم اغفر له -إن كان رجلًا، أو اللهم اغفر لها- إن كانت امرأة، أو اللهم اغفر لهم إن كانوا جماعة، اللهم اغفر لهم، وارحمهم، وعافهم، واعف عنهم، وأكرم نزلهم، ووسع مدخلهم، واغسلهم بالماء والثلج والبرد، ونقهم من الخطايا كما ينقى الثوب الأبيض من الدنس، اللهم أبدلهم دور خيرًا من دورهم، وأهلًا خيرًا من أهلهم، اللهم أدخلهم الجنة، وأعذهم من عذاب القبر ومن عذاب النار، وأفسح لهم في قبورهم ونور لهم فيها؛ إذا كانوا جماعة، وإن كان واحد:\nاللهم اغفر له... إلى آخره.\nاللهم لا تحرمنا أجره ولا تضلنا بعده، واغفر لنا وله.\nاللهم اغفر له، وثبته بالقول الثابت، كلها دعاء طيب. المقدم: أحسن الله لكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14536/الدعاء-الذي-يقال-في-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57804.mp3","categories":["الصلاة على الميت"]},{"id":16582,"question":"يسأل ويقول: في أكثر الأحيان يقف الإمام بعد صلاة الجمعة، ويقول: الصلاة على الميت الغائب فلان بن فلان، وعلى من جازت عليه الصلاة من المسلمين، هل تجوز هذه الصلاة؟","title":"هل يجوز قول الإمام بعد الجمعة: الصلاة على الغائب فلان بن فلان؟","answer":"الجواب: الصلاة على الغائب فيها تفصيل: إن الغائب ممن عرف له قدم في الإسلام، مثل داعية إلى الله مشهور، نفع الله به المسلمين، مثل أمير مشهور، نفع الله به المسلمين؛ هذا يجوز عند بعض أهل العلم؛ لأن الرسول ﷺ صلى على النجاشي ملك الحبشة لما أسلم، وآوى المهاجرين، ونصرهم، وحماهم، ثم مات، صلى عليه النبي ﷺ صلاة الغائب، ولم يحفظ عنه أنه صلى على غيره، فقال بعض أهل العلم: إن هذا خاص بـالنجاشي فقط؛ لأن الأموات كثيرون، ولم يصل عليهم النبي ﷺ. وقال آخرون: من كان مثل النجاشي له قدم في الإسلام، وله شأن؛ شرعت الصلاة عليه صلاة الغائب، وإلا فلا، وهذا القول وجيه وقريب، إذا كان له شأن في الإسلام، وإن ترك، ولم يصل عليه اكتفاء بمن صلى عليه في محله؛ فالحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15317/هل-يجوز-قول-الامام-بعد-الجمعة-الصلاة-على-الغاىب-فلان-بن-فلان ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75807.mp3","categories":["الصلاة على الميت"]},{"id":16616,"question":"المستمع (حسن . م. أ) يسأل أيضًا أسئلة فيقول: حضرت جنازتين بالمسجد: إحداهما ذكر، والأخرى أنثى، هل يجوز الجمع بينهما في صلاة واحدة؟ أو يصلي على الأنثى وحدها، وكذلك على الذكر وحده؟","title":"كيفية الصلاة على الجنائز إذا تعددت","answer":"الجواب: السنة أن يجمعا، ويصلى عليهما جميعًا؛ لأن هذا أسرع في إنجازهما، والنبي  يقول: أسرعوا بالجنازة وقد صلى على جماعة -عليه الصلاة والسلام- فالسنة أن يجمع الرجل، والمرأة، أو الرجلان، أو المرأتان، أو أكثر، ويصلى عليهم جميعًا، فإن كانا رجلان يقول: اللهم اغفر لهما، وارحمهما، وهكذا المرأتان، وإن كانوا جماعة قال: اللهم اغفر لهم، وارحمهم، وعافهم، واعف عنهم... إلى آخره، ويدعو لهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15346/كيفية-الصلاة-على-الجناىز-اذا-تعددت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75816.mp3","categories":["الصلاة على الميت"]},{"id":16641,"question":"هل يجوز للنساء الصلاة على الميت صلاة الغائب؟ علمًا بأن الميت قد مضى على وفاته شهر ونصف، أو ما يشبه ذلك، مع العلم أيضًا أنهن لم يستطعن الحضور للصلاة عليه أبدًا؟","title":"حكم صلاة النساء على الميت صلاة الغائب","answer":"الجواب: صلاة الغائب فيها خلاف بين العلماء، والأقرب، والأظهر من حيث الدليل أنه لا يصلى على الغائب إلا إذا كان من المعروفين بشيء ينفع المسلمين، كعالم كبير نفع المسلمين، كأمير نفع المسلمين مثلما صلى النبي ﷺ على النجاشي؛ لأنه نفع المسلمين، أسلم ونفع المسلمين المهاجرين إليه، فهذا يصلى عليه صلاة الغائب. وليس كل ميت يصلى عليه صلاة الغائب، إنما من له شهرة في الإسلام، وقدم في الإسلام، ونفع للمسلمين من عالم، وأمير، وكبير، نفع المسلمين؛ لا مانع من أن يصلى عليه صلاة الغائب كما فعل النبي ﷺ في النجاشي، فإنه لما بلغه خبره؛ أخبر المسلمين، وصلوا عليه صلاة الغائب، ولم يكن يصلي على عامة الناس -عليه الصلاة والسلام- فإذا كان الذي مات مشهورًا بالعلم، والدعوة إلى الله، أو مشهورًا بنفع المسلمين بماله، وجاهه، ونفعه للمسلمين، سلطان، أو أمير، أو شبهه ممن لهم قدم في الإسلام. فإذا صلى عليه المسلمون صلاة الغائب؛ فلا مانع أن تصلي عليه النساء كذلك، مثلما يصلي عليه الرجال، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15374/حكم-صلاة-النساء-على-الميت-صلاة-الغاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71704.mp3","categories":["الصلاة على الميت","قضايا المرأة"]},{"id":17043,"question":"هل يجب تسوية الصفوف في صلاة العيد والجنازة؛ لأنه من الملاحظ على بعض الناس عدم الاهتمام بذلك؟ مأجورين.","title":"حكم تسوية الصفوف في صلاة العيد والجنازة","answer":"الجواب: السنة تكميل الصف الأول فالأول في الصلوات كلها، يكمل الصف الأول فالأول في الجمعة والأعياد والجنازة إذا تيسر ذلك، يكمل الصف الأول فالأول على الأصل، على القاعدة الشرعية. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15832/حكم-تسوية-الصفوف-في-صلاة-العيد-والجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58720.mp3","categories":["صلاة العيدين","الصلاة على الميت"]},{"id":17044,"question":"عند صلاة الجنازة هل ينظر المصلي إلى موضع سجوده كما في بقية الصلوات؟ أم لا يجب ذلك؟ وماذا يفعل من فاته أكثر من تكبيرة واحدة في صلاة الجنازة؟","title":"موضع نظر المصلي في صلاة الجنازة","answer":"الجواب: السنة للمصلي في الجنازة، وغير الجنازة أن ينظر محل سجوده حتى لا يحصل عبث، ولا تساهل عن الصلاة، حتى يخشع، هذا هو الأفضل، وإذا أدرك بعض الصلاة فما أدركه هو أول صلاته، هذا هو الأفضل، وما يقضيه هو آخرها، فإذا أدرك التكبيرة الثالثة كبر، وقرأ الفاتحة، وإذا كبر إمامه الرابعة كبر، وصلى على النبي ﷺ وإذا سلم إمامه كبر، وقال: اللهم اغفر له وارحمه، ثم كبر، وسلم. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15833/موضع-نظر-المصلي-في-صلاة-الجنازة","audio":"","categories":["الصلاة على الميت"]},{"id":17079,"question":"من أسئلة هذا السائل من الأردن محمد القرالة يقول: ما حكم من مات وهو لا يصلي، ولكنه موحد؟ فهل يصلى عليه؟ وهل يدفن في مقابر المسلمين؟","title":"حكم الصلاة على تارك الصلاة ودفنه مع المسلمين","answer":"الجواب: إذا علم أنه لا يصلي فهو كافر في أرجح القولين، ولا يدفن مع المسلمين إذا علم أنه لا يصلي.  وقال بعض أهل العلم: إنه إذا كان لم يجحد وجوبها أنه يصلى عليه، ويدفن مع المسلمين، ولكن الأرجح أنه إذا علم بالبينة الشرعية أنه يترك الصلاة فإنه يكفر بذلك، لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة أخرجه مسلم في صحيحه، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر نسأل الله العافية. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15888/حكم-الصلاة-على-تارك-الصلاة-ودفنه-مع-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58819.mp3","categories":["حكم الصلاة وأهميتها","الصلاة على الميت"]},{"id":17177,"question":"إذا علم الشخص بموت قريبة له، وهو في بلد، وهذه المرأة في بلد، هل يصلي عليها صلاة الجنازة؟","title":"هل يصلى على الغائب صلاة الجنازة؟","answer":"الجواب: لا، يدعو لها بالمغفرة؛ لأن النبي ﷺ ما كان يصلي على الغائبين إلا إذا كان له شأن، كما صلى النبي ﷺ على النجاشي؛ لأن له شأنًا، ودعوة إلى الله، أكرم المهاجرين إليه، فإذا كان الميت ممن له شأن، كالأمير الصالح، والعالم الصالح.. ونحو ذلك، إذا صلي عليهم صلاة الغائب لا بأس. أما عامة الناس لا يصلى عليهم صلاة الغائب؛ لأنه مات الجم الغفير في مكة، وغيرها، ولم يصل عليهم النبي ﷺ صلاة الغائب.","link":"https://binbaz.org.sa/fatwas/15995/هل-يصلى-على-الغاىب-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59006.mp3","categories":["الصلاة على الميت"]},{"id":17442,"question":"هناك بعض الأئمة عندنا بعد السلام من الجنازة يدعو وهو لا زال واقفًا، والناس يدعون معه، فما هو حكم ما فعلوا؟","title":"حكم الدعاء بعد السلام من صلاة الجنازة","answer":"الجواب: هذا شيء لا أصل له، هذا بدعة لا أصل لها، إذا سلم الناس؛ انتهت الجنازة، وانتهى الدعاء، فالوقوف بعد السلام بالدعاء، وبالناس هذا لا أصل له فيما نعلم، بل هو بدعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16310/حكم-الدعاء-بعد-السلام-من-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83612.mp3","categories":["الصلاة على الميت"]},{"id":17515,"question":"هل تجوز صلاة الجنازة في وسط المقابر؟","title":"حكم صلاة الجنازة في وسط المقابر","answer":"الجواب: لا حرج في ذلك، صلاة الجنازة تصلى..تفعل في المقبرة وهكذا على الميت بعد الدفن، النبي ﷺ صلى على الميت بعد الدفن في المقبرة، والصلاة عليها في المقبرة مثل الصلاة على القبر سواء، فإذا وضعت هناك وصلى عليها الناس فلا حرج في ذلك. نعم. الممنوع الصلوات الأخرى.\nالمقدم: نعم؟\nالشيخ: الممنوع الصلوات ذات الركوع والسجود تمنع في المقابر، النبي ﷺ قال: لا تصلوا إلى القبور ولا تجلسوا عليها، وقال ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، قالت عائشة رضي الله عنها: يحذر ما صنعوا. وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم - يعني: من الأمم- كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك، فلا يجوز أن يصلى في القبور ولا أن يبنى عليها مسجد ولا قبة ولا غير ذلك، لا قبور أهل البيت ولا قبور العلماء ولا غيرهم، بل تجعل ضاحية مكشوفة ليس عليها بناء لا قبة ولا مسجد ولا غير ذلك، ترفع عن الأرض قدر شبر كما فعل بقبره ﷺ بالتراب الذي حفر منها، ترفع وتجعل النصائب عليها في طرفي القبر، ولا مانع أن يوضع عليها حصباء لحفظ التراب وترش بالماء لا مانع، أما أن يبنى عليها قبة أو مسجد أو حجرة خاصة فهذا لا يجوز، لا يبنى على القبر. أما السور الذي يعم المقبرة كلها ليحفظها عن سير الناس أو عن السيارة هذا لا بأس به من باب الصيانة لها، أما أن يوضع القبر تعظيمًا له قبة أو بنية أو مسجد هذا لا يجوز ، الرسول لعن من فعل ذلك عليه الصلاة والسلام، فلا يجوز للمسلمين أن يبنوا على أي قبر مسجدًا ولا قبة سواء كان من قبور الصحابة، أو كان من قبور أهل البيت، أو من قبور العلماء، أو الرؤساء والحكام، كلهم لا يبنى على قبورهم ولا يتخذ عليها مساجد، كل هذا منكر يجب الحذر منه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16435/حكم-صلاة-الجنازة-في-وسط-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83702.mp3","categories":["الصلاة على الميت"]},{"id":18031,"question":"رسالة وصلت إلى البرنامج من المستمعة فاطمة سعيد السرحاني من جيزان، أختنا تسأل جمعًا من الأسئلة، في سؤالها الأول تقول: هل للمرأة أن تصلي على الجنازة أم لا؟","title":"حكم صلاة المرأة على الجنازة","answer":"الجواب: نعم، الصلاة على الجنازة مشروعة للجميع للرجال والنساء، تصلي على الجنازة في البيت أو في المسجد، كل ذلك لا بأس به، وقد صلت عائشة والنساء على سعد بن أبي وقاص  لما توفي. فالمقصود: أن الصلاة على الجنائز مشروعة للجميع، وإنما المنهي عنه ذهابها للقبور، اتباع الجنائز إلى المقبرة، وزيارة القبور، أما صلاتها على الميت في مسجد أو في مصلى أو في بيت أهله فلا بأس بذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17061/حكم-صلاة-المراة-على-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_599/59907.mp3","categories":["الصلاة على الميت","قضايا المرأة"]},{"id":18173,"question":"يقول: أنا سر الختم محمد الحسن من المناصير، بالسودان، له سؤال يقول فيه: ما حكم صلاة الجنازة على الميت؟ هل تكون سرًا؟ أم جهرًا؟ جزاكم الله خيرًا.","title":"صفة القراءة في صلاة الجنازة","answer":"الجواب: هذا السؤال مجمل: فإن كان مراد السائل القراءة؛ فالقراءة سرًا، يقرأ في الجنازة سرًا، ويدعو سرًا، فإن كان مراده غير ذلك؛ ما فهمناه، صلاة الجنازة كلها سر، يقرأ سرًا، يدعو سرًا، ولو سمع صوته ممن حوله؛ فلا بأس، لا شيء عليه، والحمد لله، الصحابة سمعوا صوت النبي ﷺ في الدعاء على الجنازة. فالمقصود: أنه لا حرج أن يسمع صوته من حوله، قد يستفيد من حوله، لكن ليس بمشروع الجهر الذي يشوش على من حوله، إنما هو جهر خفيف، بحيث يسمع من حوله للاستفادة، ويتعلم بعض الناس من بعض، وإلا فالسنة في الجنازة ليلًا أو نهارًا: السر بالقراءة، والسر بالدعاء. نعم، لكن الجهر اليسير الذي قد يسمعه من حوله، لا يضر. نعم. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/17213/صفة-القراءة-في-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73109.mp3","categories":["الصلاة على الميت"]},{"id":18233,"question":"في ثاني أسئلة هذا السائل من اليمن يقول: هل تجوز الصلاة على الطفل الصغير؟","title":"حكم صلاة الجنازة على الطفل الصغير","answer":"الجواب: نعم يصلى عليه، الطفل الصغير يصلى عليه، ويدعى لوالديه. نعم. المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/17282/حكم-صلاة-الجنازة-على-الطفل-الصغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78218.mp3","categories":["الصلاة على الميت"]},{"id":18669,"question":"رسالة وصلت إلى البرنامج من الجمهورية العراقية، محافظة الأنبار، ناحية الكرمى، وباعث الرسالة أخونا حامد كاظم جاسم، أخونا له ثلاثة أسئلة، يقول في أحد أسئلته: إذا مات الشخص عندنا لا يصلون عليه صلاة الجنازة إلا في المقبرة، فهل هذا جائز؟وإذا أردنا دفنه صاح الجميع بصوت مرتفع لا إله إلا الله طوال فترة الدفن، وإذا أراد أحد أن يساعد أخاه في عملية الدفن طلب منه المجرفة بقوله: وحد الله، ثم بعد الفراغ من الدفن يقف الملقن على قبر الميت، فيقول كلامًا بليغًا يخاطب فيه الميت، قد يؤثر في السامعين لما فيه من عبارات التذكير بعذاب القبر ونعيمه، فما الحكم في كل هذا؟أفيدونا أثابكم الله، وسدد خطاكم.","title":"حكم صلاة الجنازة في المقبرة والتهليل عند الدفن","answer":"الجواب: أما الصلاة على الميت في المقبرة فلا بأس، فقد صلى النبي ﷺ على قبر بعدما دفن، لكن الأفضل أن يصلى عليه في المصلى المعد للجنازة أو المساجد حتى يصلي عليه جمع غفير من الناس، الأفضل لأهله أن يقدموه للمسلمين يصلون عليه في المساجد، أو في المصلى المعد لصلاة الجنازة إذا كان هناك مصلى معد لصلاة الجنازة، فإن لم يتيسر ذلك قد صُلي عليه في المقبرة فلا حرج. أما رفع الصوت بلا إله إلا الله عند الدفن، أو عند الحفر، أو عند السير بالجنازة هذا لا أصل له، بل المشروع أن الإنسان يفكر وينظر في عاقبة الموت، وما بعد الموت، ويحاسب نفسه، ولا يرفع صوته بذكر الله، ولا بغير ذلك مع الجنازة، ولا عند الدفن، ولا عند الحفر، أما كون الإنسان يتكلم بشيء عادي....، سيره من الجنازة بينه وبين نفسه من دعاء، أو ذكر لله، أو في المقبرة، أو غير ذلك فلا بأس. أما شيء متعمد، صوت عالي: وحدوه، أو لا إله إلا الله، صوت جماعي أو عند الدفن، فهذا شيء لا أصل له. وكان من عادة السلف -رحمة الله عليهم- غض الصوت عند الجنائز، والتفكير في أحوال الميت، وما يقال له، وما يقول، هكذا ينبغي للمؤمن أن يفكر عند اتباعه الجنازة، وعند حضوره للقبور، وعند حضوره الدفن، يفكر في هذه الأمور العظيمة، وماذا يقال للميت؟ وماذا يقول؟ وهل يجيب أو ما يجيب؟ يكون عنده في هذا تفكير طويل حتى ينتفع بذلك. ولا مانع من الدعاء والاستغفار بين العبد وبين نفسه، والذكر بين العبد وبين نفسه، لا بأس بهذا، أما تعمد رفع الصوت بذلك، أو أن يكون صوتًا جماعيًا فهذا لا أصل له، والسنة بعد الدفن أن يدعى للميت بالمغفرة والثبات. كان النبي ﷺ إذا فرغ من دفن الميت يقول: استغفروا لأخيكم، واسألوا له التثبيت، فإنه الآن يسأل فالسنة أن يوقف عليه بعد الدفن و يدعى له بالمغفرة والثبات. أما التلقين فهو بدعة هذا الصواب، أن يقال للميت بعد الدفن: يا فلان اذكر ما خرجت عليه من الدنيا، أنك تشهد أن لا إله إلا الله، وأن محمدًا رسول الله، وأن الإسلام دينك، وأن محمدًا نبيك، وأن القرآن إمامك، إلى غير هذا من الكلمات اللي يقولون هذا لا أصل له، جاء فيه أخبار، لكنها موضوعة غير صحيحة. والصواب في هذا، والمعتمد في هذا عند أهل السنة أن التلقين لا أصل له في سنة الرسول ﷺ بل هو بدعة، وإنما يدعى للميت بالمغفرة والثبات بعد الدفن كما أمر النبي ﷺ بذلك، هذا هو المعتمد، وهذا هو المشروع، والله المستعان، نعم. المقدم: الله المستعان جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17785/حكم-صلاة-الجنازة-في-المقبرة-والتهليل-عند-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92004.mp3","categories":["الصلاة على الميت","حمل الميت ودفنه","قضايا المرأة"]},{"id":18695,"question":"المستمع محمد آدم يسأل ويقول: هل هناك صلاة تدعى صلاة الغائب؟ ثم ما هي كيفيتها؟جزاكم الله خيرًا.","title":"مدى صحة صلاة الغائب","answer":"الجواب: لا أعرف شيئًا عن صلاة الغائب، لا أعرف شيئًا عن صلاة الغائب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17799/مدى-صحة-صلاة-الغاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73512.mp3","categories":["الصلاة على الميت"]},{"id":19200,"question":"ما حكم صلاة الغائب؟ هذا هو السؤال الثاني من أخينا السوداني، وهل تجوز أن تصلى على من لم يدفن بعد؟","title":"حكم صلاة الغائب على الميت","answer":"الجواب: الصلاة على الغائب فيها تفصيل: بعض أهل العلم يرى أنه لا يصلى على الغائب، وبعضهم يرى الصلاة عليه، لكن إذا كان الغائب له شأن في الإسلام، كـالنجاشي رحمه الله، فإن النبي ﷺ صلى على النجاشي لما مات في بلاده أخبر به الصحابة وصلى عليه صلاة الغائب، ولم يثبت عنه في الصلاة على الغائب إلا هذا الحديث، فإذا كان الغائب إمام عدل، وإمام خير صلي عليه صلاة الغائب، ولي الأمر يأمر بالصلاة عليه صلاة الغائب. وهكذا علماء الحق ودعاة الهدى، إذا صلي عليهم صلاة الغائب فهذا حسن، كما صلى النبي على النجاشي ، عليه الصلاة والسلام. أما أفراد الناس فلا تشرع الصلاة عليهم؛ لأن الرسول ﷺ ما صلى على كل غائب، إنما صلى على شخص واحد، له قدم في الإسلام، لأنه آوى المهاجرين من الصحابة الذين هاجروا إلى الحبشة آواهم ونصرهم وحماهم وأحسن إليهم، فكانت له يد عظيمة في الإسلام، فلهذا صلى عليه النبي ﷺ لما مات، وصلى عليه الصحابة مع النبي ﷺ. فمن كان بهذه المثابة له قدم في الإسلام مثلما صلى المسلمون في هذه البلاد على ضياء الحق، رئيس جمهورية الباكستان رحمه الله، لما كانت له مواقف طيبة إسلامية، أمر ولي الأمر أن يصلى عليه في الحرمين فصلي عليه؛ لأنه أهل لذلك لمواقفه الكريمة، وعنايته بتحكيم الشريعة، وأمره بها وحرصه على ذلك، نسأل الله لنا وله العفو والمغفرة. والمقصود أن من كان بهذه المثابة من حكام المسلمين وعلماء المسلمين إذا مات في بلاد الغربة أو في بلاده أيضًا جاز أن يصلي عليه من يصلي عليه من المسلمين في البلاد الأخرى، نعم. المقدم: أخونا يسأل جزئية أخرى لو تكرمتم سماحة الشيخ عن الصلاة قبل الدفن؟ الشيخ: يجوز أن يصلى عليه قبل الدفن. نعم قبل الدفن وبعده. المقدم: قبل الدفن وبعده. الشيخ: نعم. المقدم: الغائب والحاضر سواء شيخ عبد العزيز ؟ الشيخ: نعم. المقدم: الغائب والحاضر سواء. الشيخ: نعم، يصلي على الحاضر هذا معروف يصلون عليه قبل أن يدفنوه، السنة أن يصلى عليه قبل الدفن، والغائبون إذا علموا أنه مات صلوا عليه ولو قبل الدفن. المقدم: ولو قبل الدفن. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18368/حكم-صلاة-الغاىب-على-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93214.mp3","categories":["الصلاة على الميت"]},{"id":19300,"question":"يسأل أخونا ويقول: هل تجوز الصلاة على من مات وعليه دين؟ وهل تجوز الصلاة على من مات وكتب في وصيته أن يعطى بعض أولاده مالًا أكثر من البعض الآخر، أي: من التركة، أفيدونا جزاكم الله خيرًا.","title":"حكم الصلاة على من مات وعليه دين أو جار في الوصية","answer":"الجواب: نعم، يصلى على من مات وعليه دين، كان الرسول ﷺ أولًا لا يصلي على من عليه دين حتى يضمنه أحد ثم ترك ذلك عليه الصلاة والسلام، فكان يصلي على المدينين مطلقًا، وهكذا من مات وقد جار في وصيته أو فعل معصية، فإن هذا لا يمنع الصلاة عليه ما دام مسلمًا، فإنه يصلى عليه، ولا تنفذ وصيته المخالفة للشرع، وهذا إلى القضاة لا ينفذونها إلا برضا بقية الأولاد، إذا رضوا أن يعطى واحد منهم أكثر منهم فلا بأس هذا إليهم، ولكن هذا لا يمنع الصلاة، ولكن لا يجوز لمؤمن أن يوصي أو يعطي أحد أولاده أكثر؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم فلو فعل، يعني: أعطى بعضهم أكثر أو أوصى لبعضهم بأكثر فهذا إليهم، إن سمحوا فلا بأس و إلا رفعوا الأمر إلى الحاكم والحاكم ينقض الوصية ويمنع العطية الزائدة، عملاً بقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم.  المقدم: جزاكم الله خيرًا. إذًا أصحاب المعاصي المماثلة لمثل ما ذكره أخونا يصلى عليهم؟ الشيخ: نعم، يصلى عليهم، وإنما تمنع الصلاة على الكافر، أما العاصي فيصلى عليه ولو كان عاصي، ولو عرف بأنه عاصي يصلى عليه. نعم. المقدم: طالما أنه يشهد أن لا إله إلا الله. الشيخ: طالما أنه مسلم محكوم بإسلامه فإنه يصلى عليه، حتى يحكم الحاكم المعروف أو يعرف أنه مرتد بسبه الله أو سبه دين الله أو تركه الصلاة أو غير هذا من موجبات الردة. نعم، نسأل الله العافية. المقدم: بارك الله فيكم، إذًا لا تترك الصلاة على الميت إلا إذا كان غير مسلم أو كان مرتدًا؟ الشيخ: نعم.. نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18515/حكم-الصلاة-على-من-مات-وعليه-دين-او-جار-في-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89412.mp3","categories":["الصلاة على الميت"]},{"id":19430,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين - فيما يبدو أنه من العراق - أخونا له جمع من الأسئلة يسأل في سؤاله الأول ويقول: في بلدنا تقام بعد صلاة الجمعة صلاة تسمى صلاة الميت الغائب، ويجمع فيها عدد من أموات المسلمين من مختلف البلدان المجاورة لنا، ويصلون عليهم، علمًا بأن الأموات قد صلي عليهم في بلدانهم المسلمة، فما رأي الشرع في ذلك؟ جزاكم الله خيرًا.","title":"حكم صلاة الغائب بعد كل جمعة","answer":"الجواب: لا أعلم لهذا أصلًا، ولم يكن هذا من فعل النبي ﷺ ولا من فعل الصحابة  ولا من فعل أتباعهم بإحسان، والنبي ﷺ إنما صلى على النجاشي لما مات في بلاده، فأخبر أصحابه أنه مات، وصلى عليه؛ لأنه رجل مسلم قد نفع المسلمين، وآوى المهاجرين، وله شأن في الإسلام، فصلى عليه النبي ﷺ صلاة الغائب، ولم يحفظ عنه ﷺ أنه كان يصلي على كل أحد من الغائبين إذا ماتوا، إنما صلى على النجاشي. وذكر بعض أهل العلم أنه يلحق بـالنجاشي من كان مثل النجاشي كالناس الذين لهم قدم في الإسلام من دعاة الهدى، أئمة الإسلام يصلى عليهم صلاة الغائب لا بأس. أما الصلاة على عموم الناس إذا ماتوا في بلاد غائبة هذا ليس له أصل ولا ينبغي، بل هذا معناه أن الناس لا يزالون يصلون على الغياب كل وقت؛ لأن الناس يموتون في كل وقت، فلا وجه لهذا، ولا ينبغي فعله، وهو خلاف ما كان عليه رسول الله ﷺ وأصحابه، فقد مات في عهده ﷺ جم غفير، ولم يصل عليهم. فلا ينبغي أن يصلى على الغائب إلا إذا كان له شأن في الإسلام كـالنجاشي والعلماء المعروفين بالدعوة إلى الله، وأئمة الإسلام المعروفين بنصر الدين، ونحو ذلك إذا صلي عليهم لا بأس، أما عامة الناس وأن يكون ذلك طريقة ماشية سائرة يصلى على الغياب في كل وقت هذا ليس له أصل، والواجب تركه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18689/حكم-صلاة-الغاىب-بعد-كل-جمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_944/nour_94404.mp3","categories":["الصلاة على الميت"]},{"id":19480,"question":"يقول السائل من ليبيا: سماحة الشيخ! اشرحوا لنا صلاة الجنازة؟ وهل تختلف صلاة الجنازة الحاضرة عن صلاة الغائب؟ وهل يصلى على السقط؟","title":"صفة صلاة الجنازة وحكم الصلاة على السقط","answer":"الجواب: صلاة الجنازة مثلما فعل النبي ﷺ أربع تكبيرات، يكبر ثم يقرأ الفاتحة، ثم يكبر ويصلي على النبي ﷺ ثم يكبر الثالثة ويقول: اللهم اغفر لحينا وميتنا وشاهدنا وغائبنا وصغيرنا وكبيرنا وذكرنا وأنثانا، اللهم من أحييته منا فأحيه على الإسلام، ومن توفيته منا فتوفه على الإيمان ثم يدعو له إن كان رجل يقول: اللهم اغفر له وارحمه وعافه واعف عنه وأكرم نزله ووسع مدخله واغسله بالماء والثلج والبرد، ونقه من الخطايا كما ينقى الثوب الأبيض من الدنس، اللهم أبدله دارًا خيرًا من داره وأهلًا خيرًا من أهله -وإن كانت عنده زوجة- يقول وزوجًا خير من زوجه، اللهم أدخله الجنة وأعذه من عذاب القبر ومن عذاب النار، وافسح له في قبره ونور له فيه، اللهم لا تحرمنا أجره ولا تضلنا بعده واغفر لنا وله.\nوالمرأة كذلك، لكن يقول: (اللهم اغفر لها وارحمها).\nوإن كانوا جماعةً قال: (اللهم اغفر لهم وارحمهم)، ثم يكبر الرابعة ثم يسلم عن يمينه. والفرط يصلى عليه، السقط يصلى عليه مثلما يصلى على الكبير، ويدعى لوالديه بعد الثالثة: اللهم اجعله ذخرًا لوالديه وفرطًا وشفيعًا مجابًا، اللهم أعظم به أجورهما وثقل به موازينهما، وألحقه بصالح سلف المؤمنين، واجعله في كفالة إبراهيم عليه السلام، وقه برحمتك عذاب الجحيم نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18729/صفة-صلاة-الجنازة-وحكم-الصلاة-على-السقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93916.mp3","categories":["الصلاة على الميت"]}]
